     !> SORG2R: generates an m by n real matrix Q with orthonormal columns,
     !> which is defined as the first n columns of a product of k elementary
     !> reflectors of order m
     !> Q  =  H(1) H(2) . . . H(k)
     !> as returned by SGEQRF.

     pure subroutine la_sorg2r(m,n,k,a,lda,tau,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,lda,m,n
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(in) :: tau(*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,l
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input arguments
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0 .or. n > m) then
              info = -2
           else if (k < 0 .or. k > n) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('SORG2R',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) return
           ! initialise columns k+1:n to columns of the unit matrix
           do j = k + 1,n
              do l = 1,m
                 a(l,j) = zero
              end do
              a(j,j) = one
           end do
           do i = k,1,-1
              ! apply h(i) to a(i:m,i:n) from the left
              if (i < n) then
                 a(i,i) = one
                 call la_slarf('LEFT',m - i + 1,n - i,a(i,i),1,tau(i),a(i,i + 1),lda, &
                           work)
              end if
              if (i < m) call la_sscal(m - i,-tau(i),a(i + 1,i),1)
              a(i,i) = one - tau(i)
              ! set a(1:i-1,i) to zero
              do l = 1,i - 1
                 a(l,i) = zero
              end do
           end do
           return
     end subroutine la_sorg2r
