     !> SORGR2: generates an m by n real matrix Q with orthonormal rows,
     !> which is defined as the last m rows of a product of k elementary
     !> reflectors of order n
     !> Q  =  H(1) H(2) . . . H(k)
     !> as returned by SGERQF.

     pure subroutine la_sorgr2(m,n,k,a,lda,tau,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,lda,m,n
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(in) :: tau(*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,ii,j,l
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input arguments
           info = 0
           if (m < 0) then
              info = -1
           else if (n < m) then
              info = -2
           else if (k < 0 .or. k > m) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('SORGR2',-info)
              return
           end if
           ! quick return if possible
           if (m <= 0) return
           if (k < m) then
              ! initialise rows 1:m-k to rows of the unit matrix
              do j = 1,n
                 do l = 1,m - k
                    a(l,j) = zero
                 end do
                 if (j > n - m .and. j <= n - k) a(m - n + j,j) = one
              end do
           end if
           do i = 1,k
              ii = m - k + i
              ! apply h(i) to a(1:m-k+i,1:n-k+i) from the right
              a(ii,n - m + ii) = one
              call la_slarf('RIGHT',ii - 1,n - m + ii,a(ii,1),lda,tau(i),a,lda,work)

              call la_sscal(n - m + ii - 1,-tau(i),a(ii,1),lda)
              a(ii,n - m + ii) = one - tau(i)
              ! set a(m-k+i,n-k+i+1:n) to zero
              do l = n - m + ii + 1,n
                 a(ii,l) = zero
              end do
           end do
           return
     end subroutine la_sorgr2
