                 mi = m
                 ic = 1
              end if
              do i = i1,i2,i3
                 ib = min(nb,k - i + 1)
                 ! form the triangular factor of the block reflector
                 ! h = h(i) h(i+1) . . . h(i+ib-1)
                 call la_xlarft('FORWARD','COLUMNWISE',nq - i + 1,ib,a(i,i),lda,tau(i), &
                            work(iwt),ldt)
