              aii = a(i,nq - k + i)
              a(i,nq - k + i) = one
              call la_qlarf(side,mi,ni,a(i,1),lda,tau(i),c,ldc,work)
              a(i,nq - k + i) = aii
           end do
           return
     end subroutine la_qormr2
