     !> STPRFB: applies a real "triangular-pentagonal" block reflector H or its
     !> conjugate transpose H^H to a real matrix C, which is composed of two
     !> blocks A and B, either from the left or right.

     pure subroutine la_stprfb(side,trans,direct,storev,m,n,k,l,v,ldv,t,ldt,a, &
               lda,b,ldb,work,ldwork)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: direct,side,storev,trans
           integer(ilp),intent(in) :: k,l,lda,ldb,ldt,ldv,ldwork,m,n
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*),b(ldb,*)
           real(sp),intent(in) :: t(ldt,*),v(ldv,*)
           real(sp),intent(out) :: work(ldwork,*)
        ! ==========================================================================

           ! Local Scalars
           integer(ilp) :: i,j,mp,np,kp
           logical(lk) :: left,forward,column,right,backward,row
           ! Executable Statements
           ! quick return if possible
           if (m <= 0 .or. n <= 0 .or. k <= 0 .or. l < 0) return
           if (la_lsame(storev,'C')) then
              column = .true.
              row = .false.
           else if (la_lsame(storev,'R')) then
              column = .false.
              row = .true.
           else
              column = .false.
              row = .false.
           end if
           if (la_lsame(side,'L')) then
              left = .true.
              right = .false.
           else if (la_lsame(side,'R')) then
              left = .false.
              right = .true.
           else
              left = .false.
              right = .false.
           end if
           if (la_lsame(direct,'F')) then
              forward = .true.
              backward = .false.
           else if (la_lsame(direct,'B')) then
              forward = .false.
              backward = .true.
           else
              forward = .false.
              backward = .false.
           end if
       ! ---------------------------------------------------------------------------
           if (column .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (m-by-k)
              ! form  h c  or  h^h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w t w^h          or  h^h = i - w t^h w^h
              ! a = a -   t (a + v^h b)  or  a = a -   t^h (a + v^h b)
              ! b = b - v t (a + v^h b)  or  b = b - v t^h (a + v^h b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_strmm('L','U','T','N',l,n,one,v(mp,1),ldv,work,ldwork)

              call la_sgemm('T','N',l,n,m - l,one,v,ldv,b,ldb,one,work,ldwork)

              call la_sgemm('T','N',k - l,n,m,one,v(1,kp),ldv,b,ldb,zero,work(kp, &
                         1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_strmm('L','U',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_sgemm('N','N',m - l,n,k,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_sgemm('N','N',l,n,k - l,-one,v(mp,kp),ldv,work(kp,1), &
                        ldwork,one,b(mp,1),ldb)
              call la_strmm('L','U','N','N',l,n,one,v(mp,1),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (n-by-k)
              ! form  c h or  c h^h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w t w^h          or  h^h = i - w t^h w^h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t^h
              ! b = b - (a + b v) t v^h  or  b = b - (a + b v) t^h v^h
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_strmm('R','U','N','N',m,l,one,v(np,1),ldv,work,ldwork)

              call la_sgemm('N','N',m,l,n - l,one,b,ldb,v,ldv,one,work,ldwork)

              call la_sgemm('N','N',m,k - l,n,one,b,ldb,v(1,kp),ldv,zero,work(1, &
                        kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_strmm('R','U',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_sgemm('N','T',m,n - l,k,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_sgemm('N','T',m,l,k - l,-one,work(1,kp),ldwork,v(np,kp), &
                        ldv,one,b(1,np),ldb)
              call la_strmm('R','U','T','N',m,l,one,v(np,1),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (m-by-k)
                        ! [ i ]    (k-by-k)
              ! form  h c  or  h^h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w t w^h          or  h^h = i - w t^h w^h
              ! a = a -   t (a + v^h b)  or  a = a -   t^h (a + v^h b)
              ! b = b - v t (a + v^h b)  or  b = b - v t^h (a + v^h b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_strmm('L','L','T','N',l,n,one,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              call la_sgemm('T','N',l,n,m - l,one,v(mp,kp),ldv,b(mp,1),ldb,one, &
                        work(kp,1),ldwork)
              call la_sgemm('T','N',k - l,n,m,one,v,ldv,b,ldb,zero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_strmm('L','L',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_sgemm('N','N',m - l,n,k,-one,v(mp,1),ldv,work,ldwork,one,b( &
                        mp,1),ldb)
              call la_sgemm('N','N',l,n,k - l,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_strmm('L','L','N','N',l,n,one,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (n-by-k)
                        ! [ i ]    (k-by-k)
              ! form  c h  or  c h^h  where  c = [ b a ] (b is m-by-n, a is m-by-k)
              ! h = i - w t w^h          or  h^h = i - w t^h w^h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t^h
              ! b = b - (a + b v) t v^h  or  b = b - (a + b v) t^h v^h
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_strmm('R','L','N','N',m,l,one,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              call la_sgemm('N','N',m,l,n - l,one,b(1,np),ldb,v(np,kp),ldv,one, &
                        work(1,kp),ldwork)
              call la_sgemm('N','N',m,k - l,n,one,b,ldb,v,ldv,zero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_strmm('R','L',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_sgemm('N','T',m,n - l,k,-one,work,ldwork,v(np,1),ldv,one,b( &
                        1,np),ldb)
              call la_sgemm('N','T',m,l,k - l,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_strmm('R','L','T','N',m,l,one,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h^h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w^h t w          or  h^h = i - w^h t^h w
              ! a = a -     t (a + v b)  or  a = a -     t^h (a + v b)
              ! b = b - v^h t (a + v b)  or  b = b - v^h t^h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_strmm('L','L','N','N',l,n,one,v(1,mp),ldv,work,ldb)

              call la_sgemm('N','N',l,n,m - l,one,v,ldv,b,ldb,one,work,ldwork)

              call la_sgemm('N','N',k - l,n,m,one,v(kp,1),ldv,b,ldb,zero,work(kp, &
                         1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_strmm('L','U',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_sgemm('T','N',m - l,n,k,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_sgemm('T','N',l,n,k - l,-one,v(kp,mp),ldv,work(kp,1), &
                        ldwork,one,b(mp,1),ldb)
              call la_strmm('L','L','T','N',l,n,one,v(1,mp),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h^h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w^h t w            or  h^h = i - w^h t^h w
              ! a = a - (a + b v^h) t      or  a = a - (a + b v^h) t^h
              ! b = b - (a + b v^h) t v    or  b = b - (a + b v^h) t^h v
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_strmm('R','L','T','N',m,l,one,v(1,np),ldv,work,ldwork)

              call la_sgemm('N','T',m,l,n - l,one,b,ldb,v,ldv,one,work,ldwork)

              call la_sgemm('N','T',m,k - l,n,one,b,ldb,v(kp,1),ldv,zero,work(1, &
                        kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_strmm('R','U',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_sgemm('N','N',m,n - l,k,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_sgemm('N','N',m,l,k - l,-one,work(1,kp),ldwork,v(kp,np), &
                        ldv,one,b(1,np),ldb)
              call la_strmm('R','L','N','N',m,l,one,v(1,np),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h^h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w^h t w          or  h^h = i - w^h t^h w
              ! a = a -     t (a + v b)  or  a = a -     t^h (a + v b)
              ! b = b - v^h t (a + v b)  or  b = b - v^h t^h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_strmm('L','U','N','N',l,n,one,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              call la_sgemm('N','N',l,n,m - l,one,v(kp,mp),ldv,b(mp,1),ldb,one, &
                        work(kp,1),ldwork)
              call la_sgemm('N','N',k - l,n,m,one,v,ldv,b,ldb,zero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_strmm('L','L ',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_sgemm('T','N',m - l,n,k,-one,v(1,mp),ldv,work,ldwork,one,b( &
                        mp,1),ldb)
              call la_sgemm('T','N',l,n,k - l,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_strmm('L','U','T','N',l,n,one,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h^h  where  c = [ b a ] (a is m-by-k, b is m-by-n)
              ! h = i - w^h t w            or  h^h = i - w^h t^h w
              ! a = a - (a + b v^h) t      or  a = a - (a + b v^h) t^h
              ! b = b - (a + b v^h) t v    or  b = b - (a + b v^h) t^h v
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_strmm('R','U','T','N',m,l,one,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              call la_sgemm('N','T',m,l,n - l,one,b(1,np),ldb,v(kp,np),ldv,one, &
                        work(1,kp),ldwork)
              call la_sgemm('N','T',m,k - l,n,one,b,ldb,v,ldv,zero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_strmm('R','L',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_sgemm('N','N',m,n - l,k,-one,work,ldwork,v(1,np),ldv,one,b( &
                        1,np),ldb)
              call la_sgemm('N','N',m,l,k - l,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_strmm('R','U','N','N',m,l,one,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
           end if
           return
     end subroutine la_stprfb
     !> DTPRFB: applies a real "triangular-pentagonal" block reflector H or its
     !> transpose H**T to a real matrix C, which is composed of two
     !> blocks A and B, either from the left or right.

     pure subroutine la_dtprfb(side,trans,direct,storev,m,n,k,l,v,ldv,t,ldt,a, &
               lda,b,ldb,work,ldwork)
        use la_constants_dp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: direct,side,storev,trans
           integer(ilp),intent(in) :: k,l,lda,ldb,ldt,ldv,ldwork,m,n
           ! Array Arguments
           real(dp),intent(inout) :: a(lda,*),b(ldb,*)
           real(dp),intent(in) :: t(ldt,*),v(ldv,*)
           real(dp),intent(out) :: work(ldwork,*)
        ! ==========================================================================

           ! Local Scalars
           integer(ilp) :: i,j,mp,np,kp
           logical(lk) :: left,forward,column,right,backward,row
           ! Executable Statements
           ! quick return if possible
           if (m <= 0 .or. n <= 0 .or. k <= 0 .or. l < 0) return
           if (la_lsame(storev,'C')) then
              column = .true.
              row = .false.
           else if (la_lsame(storev,'R')) then
              column = .false.
              row = .true.
           else
              column = .false.
              row = .false.
           end if
           if (la_lsame(side,'L')) then
              left = .true.
              right = .false.
           else if (la_lsame(side,'R')) then
              left = .false.
              right = .true.
           else
              left = .false.
              right = .false.
           end if
           if (la_lsame(direct,'F')) then
              forward = .true.
              backward = .false.
           else if (la_lsame(direct,'B')) then
              forward = .false.
              backward = .true.
           else
              forward = .false.
              backward = .false.
           end if
       ! ---------------------------------------------------------------------------
           if (column .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (m-by-k)
              ! form  h c  or  h**t c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a -   t (a + v**t b)  or  a = a -   t**t (a + v**t b)
              ! b = b - v t (a + v**t b)  or  b = b - v t**t (a + v**t b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_dtrmm('L','U','T','N',l,n,one,v(mp,1),ldv,work,ldwork)

              call la_dgemm('T','N',l,n,m - l,one,v,ldv,b,ldb,one,work,ldwork)

              call la_dgemm('T','N',k - l,n,m,one,v(1,kp),ldv,b,ldb,zero,work(kp, &
                         1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_dtrmm('L','U',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_dgemm('N','N',m - l,n,k,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_dgemm('N','N',l,n,k - l,-one,v(mp,kp),ldv,work(kp,1), &
                        ldwork,one,b(mp,1),ldb)
              call la_dtrmm('L','U','N','N',l,n,one,v(mp,1),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (n-by-k)
              ! form  c h or  c h**t  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**t
              ! b = b - (a + b v) t v**t  or  b = b - (a + b v) t**t v**t
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_dtrmm('R','U','N','N',m,l,one,v(np,1),ldv,work,ldwork)

              call la_dgemm('N','N',m,l,n - l,one,b,ldb,v,ldv,one,work,ldwork)

              call la_dgemm('N','N',m,k - l,n,one,b,ldb,v(1,kp),ldv,zero,work(1, &
                        kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_dtrmm('R','U',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_dgemm('N','T',m,n - l,k,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_dgemm('N','T',m,l,k - l,-one,work(1,kp),ldwork,v(np,kp), &
                        ldv,one,b(1,np),ldb)
              call la_dtrmm('R','U','T','N',m,l,one,v(np,1),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (m-by-k)
                        ! [ i ]    (k-by-k)
              ! form  h c  or  h**t c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a -   t (a + v**t b)  or  a = a -   t**t (a + v**t b)
              ! b = b - v t (a + v**t b)  or  b = b - v t**t (a + v**t b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_dtrmm('L','L','T','N',l,n,one,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              call la_dgemm('T','N',l,n,m - l,one,v(mp,kp),ldv,b(mp,1),ldb,one, &
                        work(kp,1),ldwork)
              call la_dgemm('T','N',k - l,n,m,one,v,ldv,b,ldb,zero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_dtrmm('L','L',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_dgemm('N','N',m - l,n,k,-one,v(mp,1),ldv,work,ldwork,one,b( &
                        mp,1),ldb)
              call la_dgemm('N','N',l,n,k - l,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_dtrmm('L','L','N','N',l,n,one,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (n-by-k)
                        ! [ i ]    (k-by-k)
              ! form  c h  or  c h**t  where  c = [ b a ] (b is m-by-n, a is m-by-k)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**t
              ! b = b - (a + b v) t v**t  or  b = b - (a + b v) t**t v**t
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_dtrmm('R','L','N','N',m,l,one,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              call la_dgemm('N','N',m,l,n - l,one,b(1,np),ldb,v(np,kp),ldv,one, &
                        work(1,kp),ldwork)
              call la_dgemm('N','N',m,k - l,n,one,b,ldb,v,ldv,zero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_dtrmm('R','L',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_dgemm('N','T',m,n - l,k,-one,work,ldwork,v(np,1),ldv,one,b( &
                        1,np),ldb)
              call la_dgemm('N','T',m,l,k - l,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_dtrmm('R','L','T','N',m,l,one,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**t c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w**t t w          or  h**t = i - w**t t**t w
              ! a = a -     t (a + v b)  or  a = a -     t**t (a + v b)
              ! b = b - v**t t (a + v b)  or  b = b - v**t t**t (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_dtrmm('L','L','N','N',l,n,one,v(1,mp),ldv,work,ldb)

              call la_dgemm('N','N',l,n,m - l,one,v,ldv,b,ldb,one,work,ldwork)

              call la_dgemm('N','N',k - l,n,m,one,v(kp,1),ldv,b,ldb,zero,work(kp, &
                         1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_dtrmm('L','U',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_dgemm('T','N',m - l,n,k,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_dgemm('T','N',l,n,k - l,-one,v(kp,mp),ldv,work(kp,1), &
                        ldwork,one,b(mp,1),ldb)
              call la_dtrmm('L','L','T','N',l,n,one,v(1,mp),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**t  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w**t t w            or  h**t = i - w**t t**t w
              ! a = a - (a + b v**t) t      or  a = a - (a + b v**t) t**t
              ! b = b - (a + b v**t) t v    or  b = b - (a + b v**t) t**t v
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_dtrmm('R','L','T','N',m,l,one,v(1,np),ldv,work,ldwork)

              call la_dgemm('N','T',m,l,n - l,one,b,ldb,v,ldv,one,work,ldwork)

              call la_dgemm('N','T',m,k - l,n,one,b,ldb,v(kp,1),ldv,zero,work(1, &
                        kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_dtrmm('R','U',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_dgemm('N','N',m,n - l,k,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_dgemm('N','N',m,l,k - l,-one,work(1,kp),ldwork,v(kp,np), &
                        ldv,one,b(1,np),ldb)
              call la_dtrmm('R','L','N','N',m,l,one,v(1,np),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**t c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w**t t w          or  h**t = i - w**t t**t w
              ! a = a -     t (a + v b)  or  a = a -     t**t (a + v b)
              ! b = b - v**t t (a + v b)  or  b = b - v**t t**t (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_dtrmm('L','U','N','N',l,n,one,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              call la_dgemm('N','N',l,n,m - l,one,v(kp,mp),ldv,b(mp,1),ldb,one, &
                        work(kp,1),ldwork)
              call la_dgemm('N','N',k - l,n,m,one,v,ldv,b,ldb,zero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_dtrmm('L','L ',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_dgemm('T','N',m - l,n,k,-one,v(1,mp),ldv,work,ldwork,one,b( &
                        mp,1),ldb)
              call la_dgemm('T','N',l,n,k - l,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_dtrmm('L','U','T','N',l,n,one,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**t  where  c = [ b a ] (a is m-by-k, b is m-by-n)
              ! h = i - w**t t w            or  h**t = i - w**t t**t w
              ! a = a - (a + b v**t) t      or  a = a - (a + b v**t) t**t
              ! b = b - (a + b v**t) t v    or  b = b - (a + b v**t) t**t v
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_dtrmm('R','U','T','N',m,l,one,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              call la_dgemm('N','T',m,l,n - l,one,b(1,np),ldb,v(kp,np),ldv,one, &
                        work(1,kp),ldwork)
              call la_dgemm('N','T',m,k - l,n,one,b,ldb,v,ldv,zero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_dtrmm('R','L',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_dgemm('N','N',m,n - l,k,-one,work,ldwork,v(1,np),ldv,one,b( &
                        1,np),ldb)
              call la_dgemm('N','N',m,l,k - l,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_dtrmm('R','U','N','N',m,l,one,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
           end if
           return
     end subroutine la_dtprfb
#ifdef LA_WITH_XDP
     !> XTPRFB: applies a real "triangular-pentagonal" block reflector H or its
     !> transpose H**T to a real matrix C, which is composed of two
     !> blocks A and B, either from the left or right.

     pure subroutine la_xtprfb(side,trans,direct,storev,m,n,k,l,v,ldv,t,ldt,a, &
               lda,b,ldb,work,ldwork)
        use la_constants_xdp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: direct,side,storev,trans
           integer(ilp),intent(in) :: k,l,lda,ldb,ldt,ldv,ldwork,m,n
           ! Array Arguments
           real(xdp),intent(inout) :: a(lda,*),b(ldb,*)
           real(xdp),intent(in) :: t(ldt,*),v(ldv,*)
           real(xdp),intent(out) :: work(ldwork,*)
        ! ==========================================================================

           ! Local Scalars
           integer(ilp) :: i,j,mp,np,kp
           logical(lk) :: left,forward,column,right,backward,row
           ! Executable Statements
           ! quick return if possible
           if (m <= 0 .or. n <= 0 .or. k <= 0 .or. l < 0) return
           if (la_lsame(storev,'C')) then
              column = .true.
              row = .false.
           else if (la_lsame(storev,'R')) then
              column = .false.
              row = .true.
           else
              column = .false.
              row = .false.
           end if
           if (la_lsame(side,'L')) then
              left = .true.
              right = .false.
           else if (la_lsame(side,'R')) then
              left = .false.
              right = .true.
           else
              left = .false.
              right = .false.
           end if
           if (la_lsame(direct,'F')) then
              forward = .true.
              backward = .false.
           else if (la_lsame(direct,'B')) then
              forward = .false.
              backward = .true.
           else
              forward = .false.
              backward = .false.
           end if
       ! ---------------------------------------------------------------------------
           if (column .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (m-by-k)
              ! form  h c  or  h**t c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a -   t (a + v**t b)  or  a = a -   t**t (a + v**t b)
              ! b = b - v t (a + v**t b)  or  b = b - v t**t (a + v**t b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_xtrmm('L','U','T','N',l,n,one,v(mp,1),ldv,work,ldwork)

              call la_xgemm('T','N',l,n,m - l,one,v,ldv,b,ldb,one,work,ldwork)

              call la_xgemm('T','N',k - l,n,m,one,v(1,kp),ldv,b,ldb,zero,work(kp, &
                         1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_xtrmm('L','U',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_xgemm('N','N',m - l,n,k,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_xgemm('N','N',l,n,k - l,-one,v(mp,kp),ldv,work(kp,1), &
                        ldwork,one,b(mp,1),ldb)
              call la_xtrmm('L','U','N','N',l,n,one,v(mp,1),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (n-by-k)
              ! form  c h or  c h**t  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**t
              ! b = b - (a + b v) t v**t  or  b = b - (a + b v) t**t v**t
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_xtrmm('R','U','N','N',m,l,one,v(np,1),ldv,work,ldwork)

              call la_xgemm('N','N',m,l,n - l,one,b,ldb,v,ldv,one,work,ldwork)

              call la_xgemm('N','N',m,k - l,n,one,b,ldb,v(1,kp),ldv,zero,work(1, &
                        kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_xtrmm('R','U',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_xgemm('N','T',m,n - l,k,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_xgemm('N','T',m,l,k - l,-one,work(1,kp),ldwork,v(np,kp), &
                        ldv,one,b(1,np),ldb)
              call la_xtrmm('R','U','T','N',m,l,one,v(np,1),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (m-by-k)
                        ! [ i ]    (k-by-k)
              ! form  h c  or  h**t c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a -   t (a + v**t b)  or  a = a -   t**t (a + v**t b)
              ! b = b - v t (a + v**t b)  or  b = b - v t**t (a + v**t b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_xtrmm('L','L','T','N',l,n,one,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              call la_xgemm('T','N',l,n,m - l,one,v(mp,kp),ldv,b(mp,1),ldb,one, &
                        work(kp,1),ldwork)
              call la_xgemm('T','N',k - l,n,m,one,v,ldv,b,ldb,zero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_xtrmm('L','L',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_xgemm('N','N',m - l,n,k,-one,v(mp,1),ldv,work,ldwork,one,b( &
                        mp,1),ldb)
              call la_xgemm('N','N',l,n,k - l,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_xtrmm('L','L','N','N',l,n,one,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (n-by-k)
                        ! [ i ]    (k-by-k)
              ! form  c h  or  c h**t  where  c = [ b a ] (b is m-by-n, a is m-by-k)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**t
              ! b = b - (a + b v) t v**t  or  b = b - (a + b v) t**t v**t
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_xtrmm('R','L','N','N',m,l,one,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              call la_xgemm('N','N',m,l,n - l,one,b(1,np),ldb,v(np,kp),ldv,one, &
                        work(1,kp),ldwork)
              call la_xgemm('N','N',m,k - l,n,one,b,ldb,v,ldv,zero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_xtrmm('R','L',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_xgemm('N','T',m,n - l,k,-one,work,ldwork,v(np,1),ldv,one,b( &
                        1,np),ldb)
              call la_xgemm('N','T',m,l,k - l,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_xtrmm('R','L','T','N',m,l,one,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**t c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w**t t w          or  h**t = i - w**t t**t w
              ! a = a -     t (a + v b)  or  a = a -     t**t (a + v b)
              ! b = b - v**t t (a + v b)  or  b = b - v**t t**t (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_xtrmm('L','L','N','N',l,n,one,v(1,mp),ldv,work,ldb)

              call la_xgemm('N','N',l,n,m - l,one,v,ldv,b,ldb,one,work,ldwork)

              call la_xgemm('N','N',k - l,n,m,one,v(kp,1),ldv,b,ldb,zero,work(kp, &
                         1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_xtrmm('L','U',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_xgemm('T','N',m - l,n,k,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_xgemm('T','N',l,n,k - l,-one,v(kp,mp),ldv,work(kp,1), &
                        ldwork,one,b(mp,1),ldb)
              call la_xtrmm('L','L','T','N',l,n,one,v(1,mp),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**t  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w**t t w            or  h**t = i - w**t t**t w
              ! a = a - (a + b v**t) t      or  a = a - (a + b v**t) t**t
              ! b = b - (a + b v**t) t v    or  b = b - (a + b v**t) t**t v
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_xtrmm('R','L','T','N',m,l,one,v(1,np),ldv,work,ldwork)

              call la_xgemm('N','T',m,l,n - l,one,b,ldb,v,ldv,one,work,ldwork)

              call la_xgemm('N','T',m,k - l,n,one,b,ldb,v(kp,1),ldv,zero,work(1, &
                        kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_xtrmm('R','U',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_xgemm('N','N',m,n - l,k,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_xgemm('N','N',m,l,k - l,-one,work(1,kp),ldwork,v(kp,np), &
                        ldv,one,b(1,np),ldb)
              call la_xtrmm('R','L','N','N',m,l,one,v(1,np),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**t c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w**t t w          or  h**t = i - w**t t**t w
              ! a = a -     t (a + v b)  or  a = a -     t**t (a + v b)
              ! b = b - v**t t (a + v b)  or  b = b - v**t t**t (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_xtrmm('L','U','N','N',l,n,one,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              call la_xgemm('N','N',l,n,m - l,one,v(kp,mp),ldv,b(mp,1),ldb,one, &
                        work(kp,1),ldwork)
              call la_xgemm('N','N',k - l,n,m,one,v,ldv,b,ldb,zero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_xtrmm('L','L ',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_xgemm('T','N',m - l,n,k,-one,v(1,mp),ldv,work,ldwork,one,b( &
                        mp,1),ldb)
              call la_xgemm('T','N',l,n,k - l,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_xtrmm('L','U','T','N',l,n,one,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**t  where  c = [ b a ] (a is m-by-k, b is m-by-n)
              ! h = i - w**t t w            or  h**t = i - w**t t**t w
              ! a = a - (a + b v**t) t      or  a = a - (a + b v**t) t**t
              ! b = b - (a + b v**t) t v    or  b = b - (a + b v**t) t**t v
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_xtrmm('R','U','T','N',m,l,one,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              call la_xgemm('N','T',m,l,n - l,one,b(1,np),ldb,v(kp,np),ldv,one, &
                        work(1,kp),ldwork)
              call la_xgemm('N','T',m,k - l,n,one,b,ldb,v,ldv,zero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_xtrmm('R','L',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_xgemm('N','N',m,n - l,k,-one,work,ldwork,v(1,np),ldv,one,b( &
                        1,np),ldb)
              call la_xgemm('N','N',m,l,k - l,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_xtrmm('R','U','N','N',m,l,one,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
           end if
           return
     end subroutine la_xtprfb
#endif
#ifdef LA_WITH_QP
     !> QTPRFB: applies a real "triangular-pentagonal" block reflector H or its
     !> transpose H**T to a real matrix C, which is composed of two
     !> blocks A and B, either from the left or right.

     pure subroutine la_qtprfb(side,trans,direct,storev,m,n,k,l,v,ldv,t,ldt,a, &
               lda,b,ldb,work,ldwork)
        use la_constants_qp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: direct,side,storev,trans
           integer(ilp),intent(in) :: k,l,lda,ldb,ldt,ldv,ldwork,m,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(in) :: t(ldt,*),v(ldv,*)
           real(qp),intent(out) :: work(ldwork,*)
        ! ==========================================================================

           ! Local Scalars
           integer(ilp) :: i,j,mp,np,kp
           logical(lk) :: left,forward,column,right,backward,row
           ! Executable Statements
           ! quick return if possible
           if (m <= 0 .or. n <= 0 .or. k <= 0 .or. l < 0) return
           if (la_lsame(storev,'C')) then
              column = .true.
              row = .false.
           else if (la_lsame(storev,'R')) then
              column = .false.
              row = .true.
           else
              column = .false.
              row = .false.
           end if
           if (la_lsame(side,'L')) then
              left = .true.
              right = .false.
           else if (la_lsame(side,'R')) then
              left = .false.
              right = .true.
           else
              left = .false.
              right = .false.
           end if
           if (la_lsame(direct,'F')) then
              forward = .true.
              backward = .false.
           else if (la_lsame(direct,'B')) then
              forward = .false.
              backward = .true.
           else
              forward = .false.
              backward = .false.
           end if
       ! ---------------------------------------------------------------------------
           if (column .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (m-by-k)
              ! form  h c  or  h**t c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a -   t (a + v**t b)  or  a = a -   t**t (a + v**t b)
              ! b = b - v t (a + v**t b)  or  b = b - v t**t (a + v**t b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_qtrmm('L','U','T','N',l,n,one,v(mp,1),ldv,work,ldwork)

              call la_qgemm('T','N',l,n,m - l,one,v,ldv,b,ldb,one,work,ldwork)

              call la_qgemm('T','N',k - l,n,m,one,v(1,kp),ldv,b,ldb,zero,work(kp, &
                         1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_qtrmm('L','U',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_qgemm('N','N',m - l,n,k,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_qgemm('N','N',l,n,k - l,-one,v(mp,kp),ldv,work(kp,1), &
                        ldwork,one,b(mp,1),ldb)
              call la_qtrmm('L','U','N','N',l,n,one,v(mp,1),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (n-by-k)
              ! form  c h or  c h**t  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**t
              ! b = b - (a + b v) t v**t  or  b = b - (a + b v) t**t v**t
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_qtrmm('R','U','N','N',m,l,one,v(np,1),ldv,work,ldwork)

              call la_qgemm('N','N',m,l,n - l,one,b,ldb,v,ldv,one,work,ldwork)

              call la_qgemm('N','N',m,k - l,n,one,b,ldb,v(1,kp),ldv,zero,work(1, &
                        kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_qtrmm('R','U',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_qgemm('N','T',m,n - l,k,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_qgemm('N','T',m,l,k - l,-one,work(1,kp),ldwork,v(np,kp), &
                        ldv,one,b(1,np),ldb)
              call la_qtrmm('R','U','T','N',m,l,one,v(np,1),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (m-by-k)
                        ! [ i ]    (k-by-k)
              ! form  h c  or  h**t c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a -   t (a + v**t b)  or  a = a -   t**t (a + v**t b)
              ! b = b - v t (a + v**t b)  or  b = b - v t**t (a + v**t b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_qtrmm('L','L','T','N',l,n,one,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              call la_qgemm('T','N',l,n,m - l,one,v(mp,kp),ldv,b(mp,1),ldb,one, &
                        work(kp,1),ldwork)
              call la_qgemm('T','N',k - l,n,m,one,v,ldv,b,ldb,zero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_qtrmm('L','L',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_qgemm('N','N',m - l,n,k,-one,v(mp,1),ldv,work,ldwork,one,b( &
                        mp,1),ldb)
              call la_qgemm('N','N',l,n,k - l,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_qtrmm('L','L','N','N',l,n,one,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (n-by-k)
                        ! [ i ]    (k-by-k)
              ! form  c h  or  c h**t  where  c = [ b a ] (b is m-by-n, a is m-by-k)
              ! h = i - w t w**t          or  h**t = i - w t**t w**t
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**t
              ! b = b - (a + b v) t v**t  or  b = b - (a + b v) t**t v**t
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_qtrmm('R','L','N','N',m,l,one,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              call la_qgemm('N','N',m,l,n - l,one,b(1,np),ldb,v(np,kp),ldv,one, &
                        work(1,kp),ldwork)
              call la_qgemm('N','N',m,k - l,n,one,b,ldb,v,ldv,zero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_qtrmm('R','L',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_qgemm('N','T',m,n - l,k,-one,work,ldwork,v(np,1),ldv,one,b( &
                        1,np),ldb)
              call la_qgemm('N','T',m,l,k - l,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_qtrmm('R','L','T','N',m,l,one,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**t c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w**t t w          or  h**t = i - w**t t**t w
              ! a = a -     t (a + v b)  or  a = a -     t**t (a + v b)
              ! b = b - v**t t (a + v b)  or  b = b - v**t t**t (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_qtrmm('L','L','N','N',l,n,one,v(1,mp),ldv,work,ldb)

              call la_qgemm('N','N',l,n,m - l,one,v,ldv,b,ldb,one,work,ldwork)

              call la_qgemm('N','N',k - l,n,m,one,v(kp,1),ldv,b,ldb,zero,work(kp, &
                         1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_qtrmm('L','U',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_qgemm('T','N',m - l,n,k,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_qgemm('T','N',l,n,k - l,-one,v(kp,mp),ldv,work(kp,1), &
                        ldwork,one,b(mp,1),ldb)
              call la_qtrmm('L','L','T','N',l,n,one,v(1,mp),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**t  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w**t t w            or  h**t = i - w**t t**t w
              ! a = a - (a + b v**t) t      or  a = a - (a + b v**t) t**t
              ! b = b - (a + b v**t) t v    or  b = b - (a + b v**t) t**t v
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_qtrmm('R','L','T','N',m,l,one,v(1,np),ldv,work,ldwork)

              call la_qgemm('N','T',m,l,n - l,one,b,ldb,v,ldv,one,work,ldwork)

              call la_qgemm('N','T',m,k - l,n,one,b,ldb,v(kp,1),ldv,zero,work(1, &
                        kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_qtrmm('R','U',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_qgemm('N','N',m,n - l,k,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_qgemm('N','N',m,l,k - l,-one,work(1,kp),ldwork,v(kp,np), &
                        ldv,one,b(1,np),ldb)
              call la_qtrmm('R','L','N','N',m,l,one,v(1,np),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**t c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w**t t w          or  h**t = i - w**t t**t w
              ! a = a -     t (a + v b)  or  a = a -     t**t (a + v b)
              ! b = b - v**t t (a + v b)  or  b = b - v**t t**t (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_qtrmm('L','U','N','N',l,n,one,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              call la_qgemm('N','N',l,n,m - l,one,v(kp,mp),ldv,b(mp,1),ldb,one, &
                        work(kp,1),ldwork)
              call la_qgemm('N','N',k - l,n,m,one,v,ldv,b,ldb,zero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_qtrmm('L','L ',trans,'N',k,n,one,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_qgemm('T','N',m - l,n,k,-one,v(1,mp),ldv,work,ldwork,one,b( &
                        mp,1),ldb)
              call la_qgemm('T','N',l,n,k - l,-one,v,ldv,work,ldwork,one,b,ldb)

              call la_qtrmm('L','U','T','N',l,n,one,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**t  where  c = [ b a ] (a is m-by-k, b is m-by-n)
              ! h = i - w**t t w            or  h**t = i - w**t t**t w
              ! a = a - (a + b v**t) t      or  a = a - (a + b v**t) t**t
              ! b = b - (a + b v**t) t v    or  b = b - (a + b v**t) t**t v
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_qtrmm('R','U','T','N',m,l,one,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              call la_qgemm('N','T',m,l,n - l,one,b(1,np),ldb,v(kp,np),ldv,one, &
                        work(1,kp),ldwork)
              call la_qgemm('N','T',m,k - l,n,one,b,ldb,v,ldv,zero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_qtrmm('R','L',trans,'N',m,k,one,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_qgemm('N','N',m,n - l,k,-one,work,ldwork,v(1,np),ldv,one,b( &
                        1,np),ldb)
              call la_qgemm('N','N',m,l,k - l,-one,work,ldwork,v,ldv,one,b,ldb)

              call la_qtrmm('R','U','N','N',m,l,one,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
           end if
           return
     end subroutine la_qtprfb
#endif

     !> SGEMQRT: overwrites the general real M-by-N matrix C with
     !> SIDE = 'L'     SIDE = 'R'
     !> TRANS = 'N':      Q C            C Q
     !> TRANS = 'T':   Q**T C            C Q**T
     !> where Q is a real orthogonal matrix defined as the product of K
     !> elementary reflectors:
     !> Q = H(1) H(2) . . . H(K) = I - V T V**T
     !> generated using the compact WY representation as returned by SGEQRT.
     !> Q is of order M if SIDE = 'L' and of order N  if SIDE = 'R'.

     pure subroutine la_sgemqrt(side,trans,m,n,k,nb,v,ldv,t,ldt,c,ldc,work,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: side,trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,ldv,ldc,m,n,nb,ldt
           ! Array Arguments
           real(sp),intent(in) :: v(ldv,*),t(ldt,*)
           real(sp),intent(inout) :: c(ldc,*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: left,right,tran,notran
           integer(ilp) :: i,ib,ldwork,kf,q
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! Test The Input Arguments
           info = 0
           left = la_lsame(side,'L')
           right = la_lsame(side,'R')
           tran = la_lsame(trans,'T')
           notran = la_lsame(trans,'N')
           if (left) then
              ldwork = max(1,n)
              q = m
           else if (right) then
              ldwork = max(1,m)
              q = n
           end if
           if (.not. left .and. .not. right) then
              info = -1
           else if (.not. tran .and. .not. notran) then
              info = -2
           else if (m < 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (k < 0 .or. k > q) then
              info = -5
           else if (nb < 1 .or. (nb > k .and. k > 0)) then
              info = -6
           else if (ldv < max(1,q)) then
              info = -8
           else if (ldt < nb) then
              info = -10
           else if (ldc < max(1,m)) then
              info = -12
           end if
           if (info /= 0) then
              call la_xerbla('SGEMQRT',-info)
              return
           end if
           ! Quick Return If Possible
           if (m == 0 .or. n == 0 .or. k == 0) return
           if (left .and. tran) then
              do i = 1,k,nb
                 ib = min(nb,k - i + 1)
                 call la_slarfb('L','T','F','C',m - i + 1,n,ib,v(i,i),ldv,t(1,i), &
                           ldt,c(i,1),ldc,work,ldwork)
