           else if (right .and. notran) then
              do i = 1,k,nb
                 ib = min(nb,k - i + 1)
                 call la_slarfb('R','N','F','C',m,n - i + 1,ib,v(i,i),ldv,t(1,i), &
                           ldt,c(1,i),ldc,work,ldwork)
              end do
           else if (left .and. notran) then
              kf = ((k - 1)/nb)*nb + 1
              do i = kf,1,-nb
                 ib = min(nb,k - i + 1)
                 call la_slarfb('L','N','F','C',m - i + 1,n,ib,v(i,i),ldv,t(1,i), &
                           ldt,c(i,1),ldc,work,ldwork)
              end do
           else if (right .and. tran) then
              kf = ((k - 1)/nb)*nb + 1
              do i = kf,1,-nb
                 ib = min(nb,k - i + 1)
                 call la_slarfb('R','T','F','C',m,n - i + 1,ib,v(i,i),ldv,t(1,i), &
                           ldt,c(1,i),ldc,work,ldwork)
              end do
           end if
           return
     end subroutine la_sgemqrt
