                       call la_sgemm('NO TRANSPOSE','NO TRANSPOSE',m - j - jb + 1,n - j - jb + 1,jb,- &
                       one,a(j + jb,j),lda,a(j,j + jb),lda,one,a(j + jb,j + jb),lda)

