           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n
           ! Array Arguments
           real(dp),intent(inout) :: a(lda,*)
           real(dp),intent(out) :: d(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: iinfo,j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('DLAORHR_COL_GETRFNP',-info)
              return
           end if
           ! quick return if possible
           if (min(m,n) == 0) return
           ! determine the block size for this environment.
           nb = la_ilaenv(1,'DLAORHR_COL_GETRFNP',' ',m,n,-1,-1)
           if (nb <= 1 .or. nb >= min(m,n)) then
              ! use unblocked code.
              call la_dlaorhr_col_getrfnp2(m,n,a,lda,d,info)
           else
              ! use blocked code.
              do j = 1,min(m,n),nb
                 jb = min(min(m,n) - j + 1,nb)
                 ! factor diagonal and subdiagonal blocks.
                 call la_dlaorhr_col_getrfnp2(m - j + 1,jb,a(j,j),lda,d(j),iinfo)

                 if (j + jb <= n) then
                    ! compute block row of u.
                    call la_dtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,n - j - jb + 1,one, &
                              a(j,j),lda,a(j,j + jb),lda)
                    if (j + jb <= m) then
