              if (i < n) then
                 ! w(1:n-i) := c(i:m,i+1:n)^h * c(i:m,i) [use w = t(:,n)]
                 do j = 1,n - i
                    t(j,n) = (a(i,i + j))
                 end do
                 call la_dgemv('T',p,n - i,one,b(1,i + 1),ldb,b(1,i),1,one,t(1,n &
                           ),1)
                 ! c(i:m,i+1:n) = c(i:m,i+1:n) + alpha*c(i:m,i)*w(1:n-1)^h
                 alpha = -(t(i,1))
                 do j = 1,n - i
                    a(i,i + j) = a(i,i + j) + alpha*(t(j,n))
                 end do
                 call la_dger(p,n - i,alpha,b(1,i),1,t(1,n),1,b(1,i + 1),ldb)

