              ! rectangular part of b2
              call la_dgemv('T',l,i - 1 - p,alpha,b(mp,np),ldb,b(mp,i),1,zero,t( &
                        np,i),1)
              ! b1
              call la_dgemv('T',m - l,i - 1,alpha,b,ldb,b(1,i),1,one,t(1,i),1)

              ! t(1:i-1,i) := t(1:i-1,1:i-1) * t(1:i-1,i)
              call la_dtrmv('U','N','N',i - 1,t,ldt,t(1,i),1)
              ! t(i,i) = tau(i)
              t(i,i) = t(i,1)
              t(i,1) = zero
