           do i = 2,n
              ! t(1:i-1,i) := c(i:m,1:i-1)^h * (alpha * c(i:m,i))
              alpha = -t(i,1)
              do j = 1,i - 1
                 t(j,i) = zero
              end do
              p = min(i - 1,l)
              mp = min(m - l + 1,m)
              np = min(p + 1,n)
              ! triangular part of b2
              do j = 1,p
                 t(j,i) = alpha*b(m - l + j,i)
              end do
              call la_xtrmv('U','T','N',p,b(mp,1),ldb,t(1,i),1)
              ! rectangular part of b2
              call la_xgemv('T',l,i - 1 - p,alpha,b(mp,np),ldb,b(mp,i),1,zero,t( &
                        np,i),1)
              ! b1
              call la_xgemv('T',m - l,i - 1,alpha,b,ldb,b(1,i),1,one,t(1,i),1)

              ! t(1:i-1,i) := t(1:i-1,1:i-1) * t(1:i-1,i)
              call la_xtrmv('U','N','N',i - 1,t,ldt,t(1,i),1)
              ! t(i,i) = tau(i)
              t(i,i) = t(i,1)
              t(i,1) = zero
           end do
     end subroutine la_xtpqrt2
#endif
#ifdef LA_WITH_QP
     !> QTPQRT2: computes a QR factorization of a real "triangular-pentagonal"
     !> matrix C, which is composed of a triangular block A and pentagonal block B,
     !> using the compact WY representation for Q.

     pure subroutine la_qtpqrt2(m,n,l,a,lda,b,ldb,t,ldt,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,ldt,n,m,l
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: t(ldt,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,p,mp,np
           real(qp) :: alpha
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (l < 0 .or. l > min(m,n)) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,m)) then
              info = -7
           else if (ldt < max(1,n)) then
              info = -9
           end if
           if (info /= 0) then
              call la_xerbla('QTPQRT2',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. m == 0) return
           do i = 1,n
              ! generate elementary reflector h(i) to annihilate b(:,i)
              p = m - l + min(l,i)
              call la_qlarfg(p + 1,a(i,i),b(1,i),1,t(i,1))
              if (i < n) then
                 ! w(1:n-i) := c(i:m,i+1:n)^h * c(i:m,i) [use w = t(:,n)]
                 do j = 1,n - i
                    t(j,n) = (a(i,i + j))
                 end do
                 call la_qgemv('T',p,n - i,one,b(1,i + 1),ldb,b(1,i),1,one,t(1,n &
                           ),1)
                 ! c(i:m,i+1:n) = c(i:m,i+1:n) + alpha*c(i:m,i)*w(1:n-1)^h
                 alpha = -(t(i,1))
                 do j = 1,n - i
                    a(i,i + j) = a(i,i + j) + alpha*(t(j,n))
                 end do
                 call la_qger(p,n - i,alpha,b(1,i),1,t(1,n),1,b(1,i + 1),ldb)

              end if
           end do
           do i = 2,n
              ! t(1:i-1,i) := c(i:m,1:i-1)^h * (alpha * c(i:m,i))
              alpha = -t(i,1)
              do j = 1,i - 1
                 t(j,i) = zero
              end do
              p = min(i - 1,l)
              mp = min(m - l + 1,m)
              np = min(p + 1,n)
              ! triangular part of b2
              do j = 1,p
                 t(j,i) = alpha*b(m - l + j,i)
              end do
              call la_qtrmv('U','T','N',p,b(mp,1),ldb,t(1,i),1)
              ! rectangular part of b2
              call la_qgemv('T',l,i - 1 - p,alpha,b(mp,np),ldb,b(mp,i),1,zero,t( &
                        np,i),1)
              ! b1
              call la_qgemv('T',m - l,i - 1,alpha,b,ldb,b(1,i),1,one,t(1,i),1)

              ! t(1:i-1,i) := t(1:i-1,1:i-1) * t(1:i-1,i)
              call la_qtrmv('U','N','N',i - 1,t,ldt,t(1,i),1)
              ! t(i,i) = tau(i)
              t(i,i) = t(i,1)
              t(i,1) = zero
           end do
     end subroutine la_qtpqrt2
#endif

