     !> SGEQRT2: computes a QR factorization of a real M-by-N matrix A,
     !> using the compact WY representation of Q.

     pure subroutine la_sgeqrt2(m,n,a,lda,t,ldt,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldt,m,n
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: t(ldt,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,k
           real(sp) :: aii,alpha
           ! Executable Statements
           ! test the input arguments
           info = 0
           if (n < 0) then
              info = -2
           else if (m < n) then
              info = -1
           else if (lda < max(1,m)) then
              info = -4
           else if (ldt < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('SGEQRT2',-info)
              return
           end if
           k = min(m,n)
           do i = 1,k
              ! generate elem. refl. h(i) to annihilate a(i+1:m,i), tau(i) -> t(i,1)
              call la_slarfg(m - i + 1,a(i,i),a(min(i + 1,m),i),1,t(i,1))
              if (i < n) then
                 ! apply h(i) to a(i:m,i+1:n) from the left
                 aii = a(i,i)
                 a(i,i) = one
                 ! w(1:n-i) := a(i:m,i+1:n)^h * a(i:m,i) [w = t(:,n)]
                 call la_sgemv('T',m - i + 1,n - i,one,a(i,i + 1),lda,a(i,i),1,zero,t( &
                           1,n),1)
                 ! a(i:m,i+1:n) = a(i:m,i+1:n) + alpha*a(i:m,i)*w(1:n-1)^h
                 alpha = -(t(i,1))
                 call la_sger(m - i + 1,n - i,alpha,a(i,i),1,t(1,n),1,a(i,i + 1),lda &
                           )
                 a(i,i) = aii
              end if
           end do
           do i = 2,n
              aii = a(i,i)
              a(i,i) = one
              ! t(1:i-1,i) := alpha * a(i:m,1:i-1)**t * a(i:m,i)
              alpha = -t(i,1)
              call la_sgemv('T',m - i + 1,i - 1,alpha,a(i,1),lda,a(i,i),1,zero,t(1, &
                        i),1)
              a(i,i) = aii
              ! t(1:i-1,i) := t(1:i-1,1:i-1) * t(1:i-1,i)
              call la_strmv('U','N','N',i - 1,t,ldt,t(1,i),1)
                 ! t(i,i) = tau(i)
                 t(i,i) = t(i,1)
                 t(i,1) = zero
           end do
     end subroutine la_sgeqrt2
