     !> SGEQRT3: recursively computes a QR factorization of a real M-by-N
     !> matrix A, using the compact WY representation of Q.
     !> Based on the algorithm of Elmroth and Gustavson,
     !> IBM J. Res. Develop. Vol 44 No. 4 July 2000.

     pure recursive subroutine la_sgeqrt3(m,n,a,lda,t,ldt,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n,ldt
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: t(ldt,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,i1,j,j1,n1,n2,iinfo
           ! Executable Statements
           info = 0
           if (n < 0) then
              info = -2
           else if (m < n) then
              info = -1
           else if (lda < max(1,m)) then
              info = -4
           else if (ldt < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('SGEQRT3',-info)
              return
           end if
           if (n == 1) then
              ! compute householder transform when n=1
              call la_slarfg(m,a(1,1),a(min(2,m),1),1,t(1,1))
           else
              ! otherwise, split a into blocks...
              n1 = n/2
              n2 = n - n1
              j1 = min(n1 + 1,n)
              i1 = min(n + 1,m)
              ! compute a(1:m,1:n1) <- (y1,r1,t1), where q1 = i - y1 t1 y1^h
              call la_sgeqrt3(m,n1,a,lda,t,ldt,iinfo)
              ! compute a(1:m,j1:n) = q1^h a(1:m,j1:n) [workspace: t(1:n1,j1:n)]
              do j = 1,n2
                 do i = 1,n1
                    t(i,j + n1) = a(i,j + n1)
                 end do
              end do
              call la_strmm('L','L','T','U',n1,n2,one,a,lda,t(1,j1),ldt)
              call la_sgemm('T','N',n1,n2,m - n1,one,a(j1,1),lda,a(j1,j1),lda, &
                        one,t(1,j1),ldt)
              call la_strmm('L','U','T','N',n1,n2,one,t,ldt,t(1,j1),ldt)
              call la_sgemm('N','N',m - n1,n2,n1,-one,a(j1,1),lda,t(1,j1),ldt, &
                        one,a(j1,j1),lda)
              call la_strmm('L','L','N','U',n1,n2,one,a,lda,t(1,j1),ldt)
              do j = 1,n2
                 do i = 1,n1
                    a(i,j + n1) = a(i,j + n1) - t(i,j + n1)
                 end do
              end do
              ! compute a(j1:m,j1:n) <- (y2,r2,t2) where q2 = i - y2 t2 y2^h
              call la_sgeqrt3(m - n1,n2,a(j1,j1),lda,t(j1,j1),ldt,iinfo)
              ! compute t3 = t(1:n1,j1:n) = -t1 y1^h y2 t2
              do i = 1,n1
                 do j = 1,n2
                    t(i,j + n1) = (a(j + n1,i))
                 end do
              end do
              call la_strmm('R','L','N','U',n1,n2,one,a(j1,j1),lda,t(1,j1), &
                        ldt)
              call la_sgemm('T','N',n1,n2,m - n,one,a(i1,1),lda,a(i1,j1),lda, &
                        one,t(1,j1),ldt)
              call la_strmm('L','U','N','N',n1,n2,-one,t,ldt,t(1,j1),ldt)

              call la_strmm('R','U','N','N',n1,n2,one,t(j1,j1),ldt,t(1,j1), &
                        ldt)
              ! y = (y1,y2); r = [ r1  a(1:n1,j1:n) ];  t = [t1 t3]
                               ! [  0        r2     ]       [ 0 t2]
           end if
           return
     end subroutine la_sgeqrt3
     !> DGEQRT3: recursively computes a QR factorization of a real M-by-N
     !> matrix A, using the compact WY representation of Q.
     !> Based on the algorithm of Elmroth and Gustavson,
     !> IBM J. Res. Develop. Vol 44 No. 4 July 2000.

     pure recursive subroutine la_dgeqrt3(m,n,a,lda,t,ldt,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n,ldt
           ! Array Arguments
           real(dp),intent(inout) :: a(lda,*)
           real(dp),intent(out) :: t(ldt,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,i1,j,j1,n1,n2,iinfo
           ! Executable Statements
           info = 0
           if (n < 0) then
              info = -2
           else if (m < n) then
              info = -1
           else if (lda < max(1,m)) then
              info = -4
           else if (ldt < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DGEQRT3',-info)
              return
           end if
           if (n == 1) then
              ! compute householder transform when n=1
              call la_dlarfg(m,a(1,1),a(min(2,m),1),1,t(1,1))
           else
              ! otherwise, split a into blocks...
              n1 = n/2
              n2 = n - n1
              j1 = min(n1 + 1,n)
              i1 = min(n + 1,m)
              ! compute a(1:m,1:n1) <- (y1,r1,t1), where q1 = i - y1 t1 y1^h
              call la_dgeqrt3(m,n1,a,lda,t,ldt,iinfo)
              ! compute a(1:m,j1:n) = q1^h a(1:m,j1:n) [workspace: t(1:n1,j1:n)]
              do j = 1,n2
                 do i = 1,n1
                    t(i,j + n1) = a(i,j + n1)
                 end do
              end do
              call la_dtrmm('L','L','T','U',n1,n2,one,a,lda,t(1,j1),ldt)
              call la_dgemm('T','N',n1,n2,m - n1,one,a(j1,1),lda,a(j1,j1),lda, &
                        one,t(1,j1),ldt)
              call la_dtrmm('L','U','T','N',n1,n2,one,t,ldt,t(1,j1),ldt)
              call la_dgemm('N','N',m - n1,n2,n1,-one,a(j1,1),lda,t(1,j1),ldt, &
                        one,a(j1,j1),lda)
              call la_dtrmm('L','L','N','U',n1,n2,one,a,lda,t(1,j1),ldt)
              do j = 1,n2
                 do i = 1,n1
                    a(i,j + n1) = a(i,j + n1) - t(i,j + n1)
                 end do
              end do
              ! compute a(j1:m,j1:n) <- (y2,r2,t2) where q2 = i - y2 t2 y2^h
              call la_dgeqrt3(m - n1,n2,a(j1,j1),lda,t(j1,j1),ldt,iinfo)
              ! compute t3 = t(1:n1,j1:n) = -t1 y1^h y2 t2
              do i = 1,n1
                 do j = 1,n2
                    t(i,j + n1) = (a(j + n1,i))
                 end do
              end do
              call la_dtrmm('R','L','N','U',n1,n2,one,a(j1,j1),lda,t(1,j1), &
                        ldt)
              call la_dgemm('T','N',n1,n2,m - n,one,a(i1,1),lda,a(i1,j1),lda, &
                        one,t(1,j1),ldt)
              call la_dtrmm('L','U','N','N',n1,n2,-one,t,ldt,t(1,j1),ldt)

              call la_dtrmm('R','U','N','N',n1,n2,one,t(j1,j1),ldt,t(1,j1), &
                        ldt)
              ! y = (y1,y2); r = [ r1  a(1:n1,j1:n) ];  t = [t1 t3]
                               ! [  0        r2     ]       [ 0 t2]
           end if
           return
     end subroutine la_dgeqrt3
#ifdef LA_WITH_XDP
