              call la_xgeqrt3(m,n1,a,lda,t,ldt,iinfo)
              ! compute a(1:m,j1:n) = q1^h a(1:m,j1:n) [workspace: t(1:n1,j1:n)]
              do j = 1,n2
                 do i = 1,n1
                    t(i,j + n1) = a(i,j + n1)
