     !> SGERQF: computes an RQ factorization of a real M-by-N matrix A:
     !> A = R * Q.

     pure subroutine la_sgerqf(m,n,a,lda,tau,work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,lwork,m,n
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: tau(*),work(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: i,ib,iinfo,iws,k,ki,kk,ldwork,lwkopt,mu,nb,nbmin,nu, &
                     nx
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info == 0) then
              k = min(m,n)
              if (k == 0) then
                 lwkopt = 1
              else
                 nb = la_ilaenv(1,'SGERQF',' ',m,n,-1,-1)
                 lwkopt = m*nb
              end if
              work(1) = lwkopt
              if (.not. lquery) then
                 if (lwork <= 0 .or. (n > 0 .and. lwork < max(1,m))) info = -7
              end if
           end if
           if (info /= 0) then
              call la_xerbla('SGERQF',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (k == 0) then
              return
           end if
           nbmin = 2
           nx = 1
           iws = m
           if (nb > 1 .and. nb < k) then
              ! determine when to cross over from blocked to unblocked code.
              nx = max(0,la_ilaenv(3,'SGERQF',' ',m,n,-1,-1))
              if (nx < k) then
                 ! determine if workspace is large enough for blocked code.
                 ldwork = m
                 iws = ldwork*nb
                 if (lwork < iws) then
                    ! not enough workspace to use optimal nb:  reduce nb and
                    ! determine the minimum value of nb.
                    nb = lwork/ldwork
                    nbmin = max(2,la_ilaenv(2,'SGERQF',' ',m,n,-1,-1))
                 end if
              end if
           end if
           if (nb >= nbmin .and. nb < k .and. nx < k) then
              ! use blocked code initially.
              ! the last kk rows are handled by the block method.
              ki = ((k - nx - 1)/nb)*nb
              kk = min(k,ki + nb)
              do i = k - kk + ki + 1,k - kk + 1,-nb
                 ib = min(k - i + 1,nb)
                 ! compute the rq factorization of the current block
                 ! a(m-k+i:m-k+i+ib-1,1:n-k+i+ib-1)
                 call la_sgerq2(ib,n - k + i + ib - 1,a(m - k + i,1),lda,tau(i),work,iinfo)

