                    ! h = h(i+ib-1) . . . h(i+1) h(i)
                    call la_slarft('BACKWARD','ROWWISE',n - k + i + ib - 1,ib,a(m - k + i,1),lda, &
                              tau(i),work,ldwork)
                    ! apply h to a(1:m-k+i-1,1:n-k+i+ib-1) from the right
                    call la_slarfb('RIGHT','NO TRANSPOSE','BACKWARD','ROWWISE',m - k + i - 1,n - &
