               call la_qtpmqrt('R','N',m,mb - k,k,0,nb,a(i,1),lda,t(1,ctr*k + 1),ldt, &
                         c(1,1),ldc,c(1,i),ldc,work,info)
               ctr = ctr + 1
              end do
              if (ii <= n) then
               ! multiply q to the last block of c
               call la_qtpmqrt('R','N',m,kk,k,0,nb,a(ii,1),lda,t(1,ctr*k + 1),ldt, &
                         c(1,1),ldc,c(1,ii),ldc,work,info)
              end if
           end if
           work(1) = lw
           return
     end subroutine la_qlamtsqr
#endif

     !> SLAQP2: computes a QR factorization with column pivoting of
     !> the block A(OFFSET+1:M,1:N).
     !> The block A(1:OFFSET,1:N) is accordingly pivoted, but not factorized.

     pure subroutine la_slaqp2(m,n,offset,a,lda,jpvt,tau,vn1,vn2,work)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: lda,m,n,offset
           ! Array Arguments
           integer(ilp),intent(inout) :: jpvt(*)
           real(sp),intent(inout) :: a(lda,*),vn1(*),vn2(*)
           real(sp),intent(out) :: tau(*),work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,itemp,j,mn,offpi,pvt
           real(sp) :: aii,temp,temp2,tol3z
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           mn = min(m - offset,n)
           tol3z = sqrt(la_slamch('EPSILON'))
           ! compute factorization.
           loop_20: do i = 1,mn
              offpi = offset + i
              ! determine ith pivot column and swap if necessary.
              pvt = (i - 1) + la_isamax(n - i + 1,vn1(i),1)
              if (pvt /= i) then
                 call la_sswap(m,a(1,pvt),1,a(1,i),1)
                 itemp = jpvt(pvt)
                 jpvt(pvt) = jpvt(i)
                 jpvt(i) = itemp
                 vn1(pvt) = vn1(i)
                 vn2(pvt) = vn2(i)
              end if
              ! generate elementary reflector h(i).
              if (offpi < m) then
                 call la_slarfg(m - offpi + 1,a(offpi,i),a(offpi + 1,i),1,tau(i))

              else
                 call la_slarfg(1,a(m,i),a(m,i),1,tau(i))
              end if
              if (i < n) then
                 ! apply h(i)**t to a(offset+i:m,i+1:n) from the left.
                 aii = a(offpi,i)
                 a(offpi,i) = one
                 call la_slarf('LEFT',m - offpi + 1,n - i,a(offpi,i),1,tau(i),a(offpi, &
                           i + 1),lda,work(1))
                 a(offpi,i) = aii
              end if
              ! update partial column norms.
              do j = i + 1,n
                 if (vn1(j) /= zero) then
                    ! note: the following 4 lines follow from the analysis in
                    ! lapack working note 176.
                    temp = one - (abs(a(offpi,j))/vn1(j))**2
                    temp = max(temp,zero)
                    temp2 = temp*(vn1(j)/vn2(j))**2
                    if (temp2 <= tol3z) then
                       if (offpi < m) then
                          vn1(j) = la_snrm2(m - offpi,a(offpi + 1,j),1)
                          vn2(j) = vn1(j)
                       else
                          vn1(j) = zero
                          vn2(j) = zero
                       end if
                    else
                       vn1(j) = vn1(j)*sqrt(temp)
                    end if
                 end if
              end do
           end do loop_20
           return
     end subroutine la_slaqp2
