     !> SLAQPS: computes a step of QR factorization with column pivoting
     !> of a real M-by-N matrix A by using Blas-3.  It tries to factorize
     !> NB columns from A starting from the row OFFSET+1, and updates all
     !> of the matrix with Blas-3 xGEMM.
     !> In some cases, due to catastrophic cancellations, it cannot
     !> factorize NB columns.  Hence, the actual number of factorized
     !> columns is returned in KB.
     !> Block A(1:OFFSET,1:N) is accordingly pivoted, but not factorized.

     pure subroutine la_slaqps(m,n,offset,nb,kb,a,lda,jpvt,tau,vn1,vn2,auxv,f, &
               ldf)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: kb
           integer(ilp),intent(in) :: lda,ldf,m,n,nb,offset
           ! Array Arguments
           integer(ilp),intent(inout) :: jpvt(*)
           real(sp),intent(inout) :: a(lda,*),auxv(*),f(ldf,*),vn1(*),vn2(*)
           real(sp),intent(out) :: tau(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: itemp,j,k,lastrk,lsticc,pvt,rk
           real(sp) :: akk,temp,temp2,tol3z
           ! Intrinsic Functions
           intrinsic :: abs,max,min,nint,real,sqrt
           ! Executable Statements
           lastrk = min(m,n + offset)
           lsticc = 0
           k = 0
           tol3z = sqrt(la_slamch('EPSILON'))
           ! beginning of while loop.
           10 continue
           if ((k < nb) .and. (lsticc == 0)) then
              k = k + 1
              rk = offset + k
              ! determine ith pivot column and swap if necessary
              pvt = (k - 1) + la_isamax(n - k + 1,vn1(k),1)
              if (pvt /= k) then
                 call la_sswap(m,a(1,pvt),1,a(1,k),1)
                 call la_sswap(k - 1,f(pvt,1),ldf,f(k,1),ldf)
                 itemp = jpvt(pvt)
                 jpvt(pvt) = jpvt(k)
                 jpvt(k) = itemp
                 vn1(pvt) = vn1(k)
                 vn2(pvt) = vn2(k)
              end if
              ! apply previous householder reflectors to column k:
              ! a(rk:m,k) := a(rk:m,k) - a(rk:m,1:k-1)*f(k,1:k-1)**t.
              if (k > 1) then
                 call la_sgemv('NO TRANSPOSE',m - rk + 1,k - 1,-one,a(rk,1),lda,f(k,1), &
                           ldf,one,a(rk,k),1)
              end if
              ! generate elementary reflector h(k).
              if (rk < m) then
                 call la_slarfg(m - rk + 1,a(rk,k),a(rk + 1,k),1,tau(k))
              else
                 call la_slarfg(1,a(rk,k),a(rk,k),1,tau(k))
              end if
              akk = a(rk,k)
              a(rk,k) = one
              ! compute kth column of f:
              ! compute  f(k+1:n,k) := tau(k)*a(rk:m,k+1:n)**t*a(rk:m,k).
              if (k < n) then
                 call la_sgemv('TRANSPOSE',m - rk + 1,n - k,tau(k),a(rk,k + 1),lda,a(rk, &
                           k),1,zero,f(k + 1,k),1)
              end if
              ! padding f(1:k,k) with zeros.
              do j = 1,k
                 f(j,k) = zero
              end do
              ! incremental updating of f:
              ! f(1:n,k) := f(1:n,k) - tau(k)*f(1:n,1:k-1)*a(rk:m,1:k-1)**t
                          ! *a(rk:m,k).
              if (k > 1) then
                 call la_sgemv('TRANSPOSE',m - rk + 1,k - 1,-tau(k),a(rk,1),lda,a(rk,k &
                           ),1,zero,auxv(1),1)
                 call la_sgemv('NO TRANSPOSE',n,k - 1,one,f(1,1),ldf,auxv(1),1,one, &
                            f(1,k),1)
              end if
              ! update the current row of a:
              ! a(rk,k+1:n) := a(rk,k+1:n) - a(rk,1:k)*f(k+1:n,1:k)**t.
              if (k < n) then
                 call la_sgemv('NO TRANSPOSE',n - k,k,-one,f(k + 1,1),ldf,a(rk,1), &
                           lda,one,a(rk,k + 1),lda)
              end if
              ! update partial column norms.
              if (rk < lastrk) then
                 do j = k + 1,n
                    if (vn1(j) /= zero) then
                       ! note: the following 4 lines follow from the analysis in
                       ! lapack working note 176.
                       temp = abs(a(rk,j))/vn1(j)
                       temp = max(zero, (one + temp)*(one - temp))
                       temp2 = temp*(vn1(j)/vn2(j))**2
                       if (temp2 <= tol3z) then
                          vn2(j) = real(lsticc,KIND=sp)
                          lsticc = j
                       else
                          vn1(j) = vn1(j)*sqrt(temp)
                       end if
                    end if
                 end do
              end if
              a(rk,k) = akk
              ! end of while loop.
              go to 10
           end if
           kb = k
           rk = offset + kb
           ! apply the block reflector to the rest of the matrix:
           ! a(offset+kb+1:m,kb+1:n) := a(offset+kb+1:m,kb+1:n) -
                               ! a(offset+kb+1:m,1:kb)*f(kb+1:n,1:kb)**t.
           if (kb < min(n,m - offset)) then
              call la_sgemm('NO TRANSPOSE','TRANSPOSE',m - rk,n - kb,kb,-one,a(rk + 1,1), &
                        lda,f(kb + 1,1),ldf,one,a(rk + 1,kb + 1),lda)
           end if
           ! recomputation of difficult columns.
           40 continue
           if (lsticc > 0) then
              itemp = nint(vn2(lsticc),KIND=ilp)
              vn1(lsticc) = la_snrm2(m - rk,a(rk + 1,lsticc),1)
              ! note: the computation of vn1( lsticc ) relies on the fact that
              ! la_snrm2 does not fail on vectors with norm below the value of
              ! sqrt(la_dlamch('s'))
              vn2(lsticc) = vn1(lsticc)
              lsticc = itemp
              go to 40
           end if
           return
     end subroutine la_slaqps
     !> DLAQPS: computes a step of QR factorization with column pivoting
     !> of a real M-by-N matrix A by using Blas-3.  It tries to factorize
     !> NB columns from A starting from the row OFFSET+1, and updates all
     !> of the matrix with Blas-3 xGEMM.
     !> In some cases, due to catastrophic cancellations, it cannot
     !> factorize NB columns.  Hence, the actual number of factorized
     !> columns is returned in KB.
     !> Block A(1:OFFSET,1:N) is accordingly pivoted, but not factorized.

     pure subroutine la_dlaqps(m,n,offset,nb,kb,a,lda,jpvt,tau,vn1,vn2,auxv,f, &
               ldf)
        use la_constants_dp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
