     !> SORGTSQR: generates an M-by-N real matrix Q_out with orthonormal columns,
     !> which are the first N columns of a product of real orthogonal
     !> matrices of order M which are returned by SLATSQR
     !> Q_out = first_N_columns_of( Q(1)_in * Q(2)_in * ... * Q(k)_in ).
     !> See the documentation for SLATSQR.

     pure subroutine la_sorgtsqr(m,n,mb,nb,a,lda,t,ldt,work,lwork,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldt,lwork,m,n,mb,nb
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(in) :: t(ldt,*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: iinfo,ldc,lworkopt,lc,lw,nblocal,j
           ! Intrinsic Functions
           intrinsic :: real,max,min
           ! Executable Statements
           ! test the input parameters
           lquery = lwork == -1
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0 .or. m < n) then
              info = -2
           else if (mb <= n) then
              info = -3
           else if (nb < 1) then
              info = -4
           else if (lda < max(1,m)) then
              info = -6
           else if (ldt < max(1,min(nb,n))) then
              info = -8
           else
              ! test the input lwork for the dimension of the array work.
              ! this workspace is used to store array c(ldc, n) and work(lwork)
              ! in the call to la_slamtsqr. see the documentation for la_slamtsqr.
              if (lwork < 2 .and. (.not. lquery)) then
                 info = -10
              else
                 ! set block size for column blocks
                 nblocal = min(nb,n)
                 ! lwork = -1, then set the size for the array c(ldc,n)
                 ! in la_slamtsqr call and set the optimal size of the work array
                 ! work(lwork) in la_slamtsqr call.
                 ldc = m
                 lc = ldc*n
                 lw = n*nblocal
                 lworkopt = lc + lw
                 if ((lwork < max(1,lworkopt)) .and. (.not. lquery)) then
                    info = -10
                 end if
              end if
           end if
           ! handle error in the input parameters and return workspace query.
           if (info /= 0) then
              call la_xerbla('SORGTSQR',-info)
              return
           else if (lquery) then
              work(1) = real(lworkopt,KIND=sp)
              return
           end if
           ! quick return if possible
           if (min(m,n) == 0) then
              work(1) = real(lworkopt,KIND=sp)
              return
           end if
           ! (1) form explicitly the tall-skinny m-by-n left submatrix q1_in
           ! of m-by-m orthogonal matrix q_in, which is implicitly stored in
           ! the subdiagonal part of input array a and in the input array t.
           ! perform by the following operation using the routine la_slamtsqr.
               ! q1_in = q_in * ( i ), where i is a n-by-n identity matrix,
                              ! ( 0 )        0 is a (m-n)-by-n zero matrix.
           ! (1a) form m-by-n matrix in the array work(1:ldc*n) with ones
           ! on the diagonal and zeros elsewhere.
           call la_slaset('F',m,n,zero,one,work,ldc)
           ! (1b)  on input, work(1:ldc*n) stores ( i );
                                                ! ( 0 )
                 ! on output, work(1:ldc*n) stores q1_in.
           call la_slamtsqr('L','N',m,n,n,mb,nblocal,a,lda,t,ldt,work,ldc,work( &
                     lc + 1),lw,iinfo)
           ! (2) copy the result from the part of the work array (1:m,1:n)
           ! with the leading dimension ldc that starts at work(1) into
           ! the output array a(1:m,1:n) column-by-column.
           do j = 1,n
              call la_scopy(m,work((j - 1)*ldc + 1),1,a(1,j),1)
           end do
           work(1) = real(lworkopt,KIND=sp)
           return
     end subroutine la_sorgtsqr
     !> DORGTSQR: generates an M-by-N real matrix Q_out with orthonormal columns,
     !> which are the first N columns of a product of real orthogonal
     !> matrices of order M which are returned by DLATSQR
     !> Q_out = first_N_columns_of( Q(1)_in * Q(2)_in * ... * Q(k)_in ).
     !> See the documentation for DLATSQR.

     pure subroutine la_dorgtsqr(m,n,mb,nb,a,lda,t,ldt,work,lwork,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldt,lwork,m,n,mb,nb
           ! Array Arguments
           real(dp),intent(inout) :: a(lda,*)
           real(dp),intent(in) :: t(ldt,*)
