                 end if
                 nfxd = nfxd + 1
              else
                 jpvt(j) = j
              end if
           end do
           nfxd = nfxd - 1
           ! factorize fixed columns
        ! =======================
           ! compute the qr factorization of fixed columns and update
           ! remaining columns.
           if (nfxd > 0) then
              na = min(m,nfxd)
