              call la_qgeqrf(m,na,a,lda,tau,work,lwork,info)
              iws = max(iws,int(work(1),KIND=ilp))
              if (na < n) then
      ! cc         call la_qorm2r( 'left', 'transpose', m, n-na, na, a, lda,
      ! cc  $                   tau, a( 1, na+1 ), lda, work, info )
                 call la_qormqr('LEFT','TRANSPOSE',m,n - na,na,a,lda,tau,a(1,na + 1), &
                           lda,work,lwork,info)
                 iws = max(iws,int(work(1),KIND=ilp))
              end if
           end if
           ! factorize free columns
        ! ======================
           if (nfxd < minmn) then
              sm = m - nfxd
              sn = n - nfxd
              sminmn = minmn - nfxd
              ! determine the block size.
              nb = la_ilaenv(inb,'QGEQRF',' ',sm,sn,-1,-1)
              nbmin = 2
              nx = 0
              if ((nb > 1) .and. (nb < sminmn)) then
                 ! determine when to cross over from blocked to unblocked code.
                 nx = max(0,la_ilaenv(ixover,'QGEQRF',' ',sm,sn,-1,-1))
                 if (nx < sminmn) then
                    ! determine if workspace is large enough for blocked code.
                    minws = 2*sn + (sn + 1)*nb
                    iws = max(iws,minws)
                    if (lwork < minws) then
                       ! not enough workspace to use optimal nb: reduce nb and
                       ! determine the minimum value of nb.
                       nb = (lwork - 2*sn)/(sn + 1)
                       nbmin = max(2,la_ilaenv(inbmin,'QGEQRF',' ',sm,sn,-1,-1))

                    end if
                 end if
              end if
              ! initialize partial column norms. the first n elements of work
              ! store the exact column norms.
              do j = nfxd + 1,n
                 work(j) = la_qnrm2(sm,a(nfxd + 1,j),1)
                 work(n + j) = work(j)
              end do
              if ((nb >= nbmin) .and. (nb < sminmn) .and. (nx < sminmn)) then
                 ! use blocked code initially.
                 j = nfxd + 1
                 ! compute factorization: while loop.
                 topbmn = minmn - nx
                 30 continue
                 if (j <= topbmn) then
                    jb = min(nb,topbmn - j + 1)
                    ! factorize jb columns among columns j:n.
                    call la_qlaqps(m,n - j + 1,j - 1,jb,fjb,a(1,j),lda,jpvt(j),tau(j) &
                              ,work(j),work(n + j),work(2*n + 1),work(2*n + jb + 1),n - j + 1)
                    j = j + fjb
                    go to 30
                 end if
              else
                 j = nfxd + 1
              end if
              ! use unblocked code to factor the last or only block.
              if (j <= minmn) call la_qlaqp2(m,n - j + 1,j - 1,a(1,j),lda,jpvt(j),tau(j), &
                         work(j),work(n + j),work(2*n + 1))
           end if
           work(1) = iws
           return
     end subroutine la_qgeqp3
