     !> applied to an M-by-N matrix A with orthonormal columns, where each
     !> element is bounded by one in absolute value. With the choice of
     !> the matrix S above, one can show that the diagonal element at each
     !> step of Gaussian elimination is the largest (in absolute value) in
     !> the column on or below the diagonal, so that no pivoting is required
     !> for numerical stability [1].
     !> For more details on the Householder reconstruction algorithm,
     !> including the modified LU factorization, see [1].
     !> This is the recursive version of the LU factorization algorithm.
     !> Denote A - S by B. The algorithm divides the matrix B into four
     !> submatrices:
     !> [  B11 | B12  ]  where B11 is n1 by n1,
     !> B = [ -----|----- ]        B21 is (m-n1) by n1,
     !> [  B21 | B22  ]        B12 is n1 by n2,
     !> B22 is (m-n1) by n2,
     !> with n1 = min(m,n)/2, n2 = n-n1.
     !> The subroutine calls itself to factor B11, solves for B21,
     !> solves for B12, updates B22, then calls itself to factor B22.
     !> For more details on the recursive LU algorithm, see [2].
     !> WLAUNHR_COL_GETRFNP2 is called to factorize a block by the blocked
     !> routine WLAUNHR_COL_GETRFNP, which uses blocked code calling
     !> Level 3 BLAS to update the submatrix. However, WLAUNHR_COL_GETRFNP2
     !> is self-sufficient and can be used without WLAUNHR_COL_GETRFNP.
     !> [1] "Reconstructing Householder vectors from tall-skinny QR",
     !> G. Ballard, J. Demmel, L. Grigori, M. Jacquelin, H.D. Nguyen,
     !> E. Solomonik, J. Parallel Distrib. Comput.,
     !> vol. 85, pp. 3-31, 2015.
     !> [2] "Recursion leads to automatic variable blocking for dense linear
     !> algebra algorithms", F. Gustavson, IBM J. of Res. and Dev.,
     !> vol. 41, no. 6, pp. 737-755, 1997.

     pure recursive subroutine la_wlaunhr_col_getrfnp2(m,n,a,lda,d,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n
           ! Array Arguments
           complex(qp),intent(inout) :: a(lda,*)
           complex(qp),intent(out) :: d(*)
        ! =====================================================================

           ! Local Scalars
           real(qp) :: sfmin
           integer(ilp) :: i,iinfo,n1,n2
           complex(qp) :: z
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,aimag,sign,max,min
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=qp)) + abs(aimag(z))
           ! Executable Statements
           ! test the input parameters
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('WLAUNHR_COL_GETRFNP2',-info)
              return
           end if
           ! quick return if possible
           if (min(m,n) == 0) return
           if (m == 1) then
              ! one row case, (also recursion termination case),
              ! use unblocked code
              ! transfer the sign
              d(1) = cmplx(-sign(one,real(a(1,1),KIND=qp)),KIND=qp)
              ! construct the row of u
              a(1,1) = a(1,1) - d(1)
           else if (n == 1) then
              ! one column case, (also recursion termination case),
              ! use unblocked code
              ! transfer the sign
              d(1) = cmplx(-sign(one,real(a(1,1),KIND=qp)),KIND=qp)
              ! construct the row of u
              a(1,1) = a(1,1) - d(1)
              ! scale the elements 2:m of the column
              ! determine machine safe minimum
              sfmin = la_qlamch('S')
              ! construct the subdiagonal elements of l
              if (cabs1(a(1,1)) >= sfmin) then
                 call la_wscal(m - 1,cone/a(1,1),a(2,1),1)
              else
                 do i = 2,m
                    a(i,1) = a(i,1)/a(1,1)
                 end do
              end if
           else
              ! divide the matrix b into four submatrices
              n1 = min(m,n)/2
              n2 = n - n1
              ! factor b11, recursive call
              call la_wlaunhr_col_getrfnp2(n1,n1,a,lda,d,iinfo)
              ! solve for b21
              call la_wtrsm('R','U','N','N',m - n1,n1,cone,a,lda,a(n1 + 1,1),lda)

              ! solve for b12
              call la_wtrsm('L','L','N','U',n1,n2,cone,a,lda,a(1,n1 + 1),lda)

              ! update b22, i.e. compute the schur complement
              ! b22 := b22 - b21*b12
              call la_wgemm('N','N',m - n1,n2,n1,-cone,a(n1 + 1,1),lda,a(1,n1 + 1), &
                        lda,cone,a(n1 + 1,n1 + 1),lda)
              ! factor b22, recursive call
              call la_wlaunhr_col_getrfnp2(m - n1,n2,a(n1 + 1,n1 + 1),lda,d(n1 + 1),iinfo)

           end if
           return
     end subroutine la_wlaunhr_col_getrfnp2
#endif

     !> CTPQRT2: computes a QR factorization of a complex "triangular-pentagonal"
     !> matrix C, which is composed of a triangular block A and pentagonal block B,
     !> using the compact WY representation for Q.

     pure subroutine la_ctpqrt2(m,n,l,a,lda,b,ldb,t,ldt,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,ldt,n,m,l
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*),b(ldb,*)
           complex(sp),intent(out) :: t(ldt,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,p,mp,np
           complex(sp) :: alpha
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (l < 0 .or. l > min(m,n)) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,m)) then
              info = -7
           else if (ldt < max(1,n)) then
              info = -9
           end if
           if (info /= 0) then
              call la_xerbla('CTPQRT2',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. m == 0) return
           do i = 1,n
              ! generate elementary reflector h(i) to annihilate b(:,i)
              p = m - l + min(l,i)
              call la_clarfg(p + 1,a(i,i),b(1,i),1,t(i,1))
              if (i < n) then
                 ! w(1:n-i) := c(i:m,i+1:n)**h * c(i:m,i) [use w = t(:,n)]
                 do j = 1,n - i
                    t(j,n) = conjg(a(i,i + j))
                 end do
                 call la_cgemv('C',p,n - i,cone,b(1,i + 1),ldb,b(1,i),1,cone,t(1, &
                           n),1)
                 ! c(i:m,i+1:n) = c(i:m,i+1:n) + alpha*c(i:m,i)*w(1:n-1)**h
                 alpha = -conjg(t(i,1))
                 do j = 1,n - i
                    a(i,i + j) = a(i,i + j) + alpha*conjg(t(j,n))
                 end do
                 call la_cgerc(p,n - i,alpha,b(1,i),1,t(1,n),1,b(1,i + 1),ldb)

              end if
           end do
           do i = 2,n
              ! t(1:i-1,i) := c(i:m,1:i-1)**h * (alpha * c(i:m,i))
              alpha = -t(i,1)
              do j = 1,i - 1
                 t(j,i) = czero
              end do
              p = min(i - 1,l)
              mp = min(m - l + 1,m)
              np = min(p + 1,n)
              ! triangular part of b2
              do j = 1,p
                 t(j,i) = alpha*b(m - l + j,i)
              end do
              call la_ctrmv('U','C','N',p,b(mp,1),ldb,t(1,i),1)
              ! rectangular part of b2
              call la_cgemv('C',l,i - 1 - p,alpha,b(mp,np),ldb,b(mp,i),1,czero,t( &
                        np,i),1)
              ! b1
              call la_cgemv('C',m - l,i - 1,alpha,b,ldb,b(1,i),1,cone,t(1,i),1)

              ! t(1:i-1,i) := t(1:i-1,1:i-1) * t(1:i-1,i)
              call la_ctrmv('U','N','N',i - 1,t,ldt,t(1,i),1)
              ! t(i,i) = tau(i)
              t(i,i) = t(i,1)
              t(i,1) = czero
           end do
     end subroutine la_ctpqrt2
     !> ZTPQRT2: computes a QR factorization of a complex "triangular-pentagonal"
     !> matrix C, which is composed of a triangular block A and pentagonal block B,
