     !> CTPRFB: applies a complex "triangular-pentagonal" block reflector H or its
     !> conjugate transpose H**H to a complex matrix C, which is composed of two
     !> blocks A and B, either from the left or right.

     pure subroutine la_ctprfb(side,trans,direct,storev,m,n,k,l,v,ldv,t,ldt,a, &
               lda,b,ldb,work,ldwork)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: direct,side,storev,trans
           integer(ilp),intent(in) :: k,l,lda,ldb,ldt,ldv,ldwork,m,n
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*),b(ldb,*)
           complex(sp),intent(in) :: t(ldt,*),v(ldv,*)
           complex(sp),intent(out) :: work(ldwork,*)
        ! ==========================================================================

           ! Local Scalars
           integer(ilp) :: i,j,mp,np,kp
           logical(lk) :: left,forward,column,right,backward,row
           ! Intrinsic Functions
           intrinsic :: conjg
           ! Executable Statements
           ! quick return if possible
           if (m <= 0 .or. n <= 0 .or. k <= 0 .or. l < 0) return
           if (la_lsame(storev,'C')) then
              column = .true.
              row = .false.
           else if (la_lsame(storev,'R')) then
              column = .false.
              row = .true.
           else
              column = .false.
              row = .false.
           end if
           if (la_lsame(side,'L')) then
              left = .true.
              right = .false.
           else if (la_lsame(side,'R')) then
              left = .false.
              right = .true.
           else
              left = .false.
              right = .false.
           end if
           if (la_lsame(direct,'F')) then
              forward = .true.
              backward = .false.
           else if (la_lsame(direct,'B')) then
              forward = .false.
              backward = .true.
           else
              forward = .false.
              backward = .false.
           end if
       ! ---------------------------------------------------------------------------
           if (column .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (m-by-k)
              ! form  h c  or  h**h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a -   t (a + v**h b)  or  a = a -   t**h (a + v**h b)
              ! b = b - v t (a + v**h b)  or  b = b - v t**h (a + v**h b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_ctrmm('L','U','C','N',l,n,cone,v(mp,1),ldv,work,ldwork)

              call la_cgemm('C','N',l,n,m - l,cone,v,ldv,b,ldb,cone,work,ldwork)

              call la_cgemm('C','N',k - l,n,m,cone,v(1,kp),ldv,b,ldb,czero,work( &
                        kp,1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ctrmm('L','U',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_cgemm('N','N',m - l,n,k,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_cgemm('N','N',l,n,k - l,-cone,v(mp,kp),ldv,work(kp,1), &
                        ldwork,cone,b(mp,1),ldb)
              call la_ctrmm('L','U','N','N',l,n,cone,v(mp,1),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (n-by-k)
              ! form  c h or  c h**h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**h
              ! b = b - (a + b v) t v**h  or  b = b - (a + b v) t**h v**h
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_ctrmm('R','U','N','N',m,l,cone,v(np,1),ldv,work,ldwork)

              call la_cgemm('N','N',m,l,n - l,cone,b,ldb,v,ldv,cone,work,ldwork)

              call la_cgemm('N','N',m,k - l,n,cone,b,ldb,v(1,kp),ldv,czero,work( &
                        1,kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ctrmm('R','U',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_cgemm('N','C',m,n - l,k,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_cgemm('N','C',m,l,k - l,-cone,work(1,kp),ldwork,v(np,kp), &
                        ldv,cone,b(1,np),ldb)
              call la_ctrmm('R','U','C','N',m,l,cone,v(np,1),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (m-by-k)
                        ! [ i ]    (k-by-k)
              ! form  h c  or  h**h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a -   t (a + v**h b)  or  a = a -   t**h (a + v**h b)
              ! b = b - v t (a + v**h b)  or  b = b - v t**h (a + v**h b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_ctrmm('L','L','C','N',l,n,cone,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              call la_cgemm('C','N',l,n,m - l,cone,v(mp,kp),ldv,b(mp,1),ldb, &
                        cone,work(kp,1),ldwork)
              call la_cgemm('C','N',k - l,n,m,cone,v,ldv,b,ldb,czero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ctrmm('L','L',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_cgemm('N','N',m - l,n,k,-cone,v(mp,1),ldv,work,ldwork,cone, &
                        b(mp,1),ldb)
              call la_cgemm('N','N',l,n,k - l,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_ctrmm('L','L','N','N',l,n,cone,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (n-by-k)
                        ! [ i ]    (k-by-k)
              ! form  c h  or  c h**h  where  c = [ b a ] (b is m-by-n, a is m-by-k)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**h
              ! b = b - (a + b v) t v**h  or  b = b - (a + b v) t**h v**h
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_ctrmm('R','L','N','N',m,l,cone,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              call la_cgemm('N','N',m,l,n - l,cone,b(1,np),ldb,v(np,kp),ldv, &
                        cone,work(1,kp),ldwork)
              call la_cgemm('N','N',m,k - l,n,cone,b,ldb,v,ldv,czero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ctrmm('R','L',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_cgemm('N','C',m,n - l,k,-cone,work,ldwork,v(np,1),ldv,cone, &
                        b(1,np),ldb)
              call la_cgemm('N','C',m,l,k - l,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_ctrmm('R','L','C','N',m,l,cone,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w**h t w          or  h**h = i - w**h t**h w
              ! a = a -     t (a + v b)  or  a = a -     t**h (a + v b)
              ! b = b - v**h t (a + v b)  or  b = b - v**h t**h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_ctrmm('L','L','N','N',l,n,cone,v(1,mp),ldv,work,ldb)

              call la_cgemm('N','N',l,n,m - l,cone,v,ldv,b,ldb,cone,work,ldwork)

              call la_cgemm('N','N',k - l,n,m,cone,v(kp,1),ldv,b,ldb,czero,work( &
                        kp,1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ctrmm('L','U',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_cgemm('C','N',m - l,n,k,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_cgemm('C','N',l,n,k - l,-cone,v(kp,mp),ldv,work(kp,1), &
                        ldwork,cone,b(mp,1),ldb)
              call la_ctrmm('L','L','C','N',l,n,cone,v(1,mp),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w**h t w            or  h**h = i - w**h t**h w
              ! a = a - (a + b v**h) t      or  a = a - (a + b v**h) t**h
              ! b = b - (a + b v**h) t v    or  b = b - (a + b v**h) t**h v
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_ctrmm('R','L','C','N',m,l,cone,v(1,np),ldv,work,ldwork)

              call la_cgemm('N','C',m,l,n - l,cone,b,ldb,v,ldv,cone,work,ldwork)

              call la_cgemm('N','C',m,k - l,n,cone,b,ldb,v(kp,1),ldv,czero,work( &
                        1,kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ctrmm('R','U',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_cgemm('N','N',m,n - l,k,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_cgemm('N','N',m,l,k - l,-cone,work(1,kp),ldwork,v(kp,np), &
                        ldv,cone,b(1,np),ldb)
              call la_ctrmm('R','L','N','N',m,l,cone,v(1,np),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w**h t w          or  h**h = i - w**h t**h w
              ! a = a -     t (a + v b)  or  a = a -     t**h (a + v b)
              ! b = b - v**h t (a + v b)  or  b = b - v**h t**h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_ctrmm('L','U','N','N',l,n,cone,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              call la_cgemm('N','N',l,n,m - l,cone,v(kp,mp),ldv,b(mp,1),ldb, &
                        cone,work(kp,1),ldwork)
              call la_cgemm('N','N',k - l,n,m,cone,v,ldv,b,ldb,czero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ctrmm('L','L ',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_cgemm('C','N',m - l,n,k,-cone,v(1,mp),ldv,work,ldwork,cone, &
                        b(mp,1),ldb)
              call la_cgemm('C','N',l,n,k - l,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_ctrmm('L','U','C','N',l,n,cone,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**h  where  c = [ b a ] (a is m-by-k, b is m-by-n)
              ! h = i - w**h t w            or  h**h = i - w**h t**h w
              ! a = a - (a + b v**h) t      or  a = a - (a + b v**h) t**h
              ! b = b - (a + b v**h) t v    or  b = b - (a + b v**h) t**h v
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_ctrmm('R','U','C','N',m,l,cone,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              call la_cgemm('N','C',m,l,n - l,cone,b(1,np),ldb,v(kp,np),ldv, &
                        cone,work(1,kp),ldwork)
              call la_cgemm('N','C',m,k - l,n,cone,b,ldb,v,ldv,czero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ctrmm('R','L',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_cgemm('N','N',m,n - l,k,-cone,work,ldwork,v(1,np),ldv,cone, &
                        b(1,np),ldb)
              call la_cgemm('N','N',m,l,k - l,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_ctrmm('R','U','N','N',m,l,cone,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
           end if
           return
     end subroutine la_ctprfb
     !> ZTPRFB: applies a complex "triangular-pentagonal" block reflector H or its
     !> conjugate transpose H**H to a complex matrix C, which is composed of two
     !> blocks A and B, either from the left or right.

     pure subroutine la_ztprfb(side,trans,direct,storev,m,n,k,l,v,ldv,t,ldt,a, &
               lda,b,ldb,work,ldwork)
        use la_constants_dp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: direct,side,storev,trans
           integer(ilp),intent(in) :: k,l,lda,ldb,ldt,ldv,ldwork,m,n
           ! Array Arguments
           complex(dp),intent(inout) :: a(lda,*),b(ldb,*)
           complex(dp),intent(in) :: t(ldt,*),v(ldv,*)
           complex(dp),intent(out) :: work(ldwork,*)
        ! ==========================================================================

           ! Local Scalars
           integer(ilp) :: i,j,mp,np,kp
           logical(lk) :: left,forward,column,right,backward,row
           ! Intrinsic Functions
           intrinsic :: conjg
           ! Executable Statements
           ! quick return if possible
           if (m <= 0 .or. n <= 0 .or. k <= 0 .or. l < 0) return
           if (la_lsame(storev,'C')) then
              column = .true.
              row = .false.
           else if (la_lsame(storev,'R')) then
              column = .false.
              row = .true.
           else
              column = .false.
              row = .false.
           end if
           if (la_lsame(side,'L')) then
              left = .true.
              right = .false.
           else if (la_lsame(side,'R')) then
              left = .false.
              right = .true.
           else
              left = .false.
              right = .false.
           end if
           if (la_lsame(direct,'F')) then
              forward = .true.
              backward = .false.
           else if (la_lsame(direct,'B')) then
              forward = .false.
              backward = .true.
           else
              forward = .false.
              backward = .false.
           end if
       ! ---------------------------------------------------------------------------
           if (column .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (m-by-k)
              ! form  h c  or  h**h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a -   t (a + v**h b)  or  a = a -   t**h (a + v**h b)
              ! b = b - v t (a + v**h b)  or  b = b - v t**h (a + v**h b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_ztrmm('L','U','C','N',l,n,cone,v(mp,1),ldv,work,ldwork)

              call la_zgemm('C','N',l,n,m - l,cone,v,ldv,b,ldb,cone,work,ldwork)

              call la_zgemm('C','N',k - l,n,m,cone,v(1,kp),ldv,b,ldb,czero,work( &
                        kp,1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ztrmm('L','U',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_zgemm('N','N',m - l,n,k,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_zgemm('N','N',l,n,k - l,-cone,v(mp,kp),ldv,work(kp,1), &
                        ldwork,cone,b(mp,1),ldb)
              call la_ztrmm('L','U','N','N',l,n,cone,v(mp,1),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (n-by-k)
              ! form  c h or  c h**h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**h
              ! b = b - (a + b v) t v**h  or  b = b - (a + b v) t**h v**h
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_ztrmm('R','U','N','N',m,l,cone,v(np,1),ldv,work,ldwork)

              call la_zgemm('N','N',m,l,n - l,cone,b,ldb,v,ldv,cone,work,ldwork)

              call la_zgemm('N','N',m,k - l,n,cone,b,ldb,v(1,kp),ldv,czero,work( &
                        1,kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ztrmm('R','U',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_zgemm('N','C',m,n - l,k,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_zgemm('N','C',m,l,k - l,-cone,work(1,kp),ldwork,v(np,kp), &
                        ldv,cone,b(1,np),ldb)
              call la_ztrmm('R','U','C','N',m,l,cone,v(np,1),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (m-by-k)
                        ! [ i ]    (k-by-k)
              ! form  h c  or  h**h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a -   t (a + v**h b)  or  a = a -   t**h (a + v**h b)
              ! b = b - v t (a + v**h b)  or  b = b - v t**h (a + v**h b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_ztrmm('L','L','C','N',l,n,cone,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              call la_zgemm('C','N',l,n,m - l,cone,v(mp,kp),ldv,b(mp,1),ldb, &
                        cone,work(kp,1),ldwork)
              call la_zgemm('C','N',k - l,n,m,cone,v,ldv,b,ldb,czero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ztrmm('L','L',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_zgemm('N','N',m - l,n,k,-cone,v(mp,1),ldv,work,ldwork,cone, &
                        b(mp,1),ldb)
              call la_zgemm('N','N',l,n,k - l,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_ztrmm('L','L','N','N',l,n,cone,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (n-by-k)
                        ! [ i ]    (k-by-k)
              ! form  c h  or  c h**h  where  c = [ b a ] (b is m-by-n, a is m-by-k)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**h
              ! b = b - (a + b v) t v**h  or  b = b - (a + b v) t**h v**h
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_ztrmm('R','L','N','N',m,l,cone,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              call la_zgemm('N','N',m,l,n - l,cone,b(1,np),ldb,v(np,kp),ldv, &
                        cone,work(1,kp),ldwork)
              call la_zgemm('N','N',m,k - l,n,cone,b,ldb,v,ldv,czero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ztrmm('R','L',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_zgemm('N','C',m,n - l,k,-cone,work,ldwork,v(np,1),ldv,cone, &
                        b(1,np),ldb)
              call la_zgemm('N','C',m,l,k - l,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_ztrmm('R','L','C','N',m,l,cone,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w**h t w          or  h**h = i - w**h t**h w
              ! a = a -     t (a + v b)  or  a = a -     t**h (a + v b)
              ! b = b - v**h t (a + v b)  or  b = b - v**h t**h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_ztrmm('L','L','N','N',l,n,cone,v(1,mp),ldv,work,ldb)

              call la_zgemm('N','N',l,n,m - l,cone,v,ldv,b,ldb,cone,work,ldwork)

              call la_zgemm('N','N',k - l,n,m,cone,v(kp,1),ldv,b,ldb,czero,work( &
                        kp,1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ztrmm('L','U',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_zgemm('C','N',m - l,n,k,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_zgemm('C','N',l,n,k - l,-cone,v(kp,mp),ldv,work(kp,1), &
                        ldwork,cone,b(mp,1),ldb)
              call la_ztrmm('L','L','C','N',l,n,cone,v(1,mp),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w**h t w            or  h**h = i - w**h t**h w
              ! a = a - (a + b v**h) t      or  a = a - (a + b v**h) t**h
              ! b = b - (a + b v**h) t v    or  b = b - (a + b v**h) t**h v
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_ztrmm('R','L','C','N',m,l,cone,v(1,np),ldv,work,ldwork)

              call la_zgemm('N','C',m,l,n - l,cone,b,ldb,v,ldv,cone,work,ldwork)

              call la_zgemm('N','C',m,k - l,n,cone,b,ldb,v(kp,1),ldv,czero,work( &
                        1,kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ztrmm('R','U',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_zgemm('N','N',m,n - l,k,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_zgemm('N','N',m,l,k - l,-cone,work(1,kp),ldwork,v(kp,np), &
                        ldv,cone,b(1,np),ldb)
              call la_ztrmm('R','L','N','N',m,l,cone,v(1,np),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w**h t w          or  h**h = i - w**h t**h w
              ! a = a -     t (a + v b)  or  a = a -     t**h (a + v b)
              ! b = b - v**h t (a + v b)  or  b = b - v**h t**h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_ztrmm('L','U','N','N',l,n,cone,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              call la_zgemm('N','N',l,n,m - l,cone,v(kp,mp),ldv,b(mp,1),ldb, &
                        cone,work(kp,1),ldwork)
              call la_zgemm('N','N',k - l,n,m,cone,v,ldv,b,ldb,czero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ztrmm('L','L ',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_zgemm('C','N',m - l,n,k,-cone,v(1,mp),ldv,work,ldwork,cone, &
                        b(mp,1),ldb)
              call la_zgemm('C','N',l,n,k - l,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_ztrmm('L','U','C','N',l,n,cone,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**h  where  c = [ b a ] (a is m-by-k, b is m-by-n)
              ! h = i - w**h t w            or  h**h = i - w**h t**h w
              ! a = a - (a + b v**h) t      or  a = a - (a + b v**h) t**h
              ! b = b - (a + b v**h) t v    or  b = b - (a + b v**h) t**h v
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_ztrmm('R','U','C','N',m,l,cone,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              call la_zgemm('N','C',m,l,n - l,cone,b(1,np),ldb,v(kp,np),ldv, &
                        cone,work(1,kp),ldwork)
              call la_zgemm('N','C',m,k - l,n,cone,b,ldb,v,ldv,czero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ztrmm('R','L',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_zgemm('N','N',m,n - l,k,-cone,work,ldwork,v(1,np),ldv,cone, &
                        b(1,np),ldb)
              call la_zgemm('N','N',m,l,k - l,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_ztrmm('R','U','N','N',m,l,cone,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
           end if
           return
     end subroutine la_ztprfb
#ifdef LA_WITH_XDP
     !> YTPRFB: applies a complex "triangular-pentagonal" block reflector H or its
     !> conjugate transpose H**H to a complex matrix C, which is composed of two
     !> blocks A and B, either from the left or right.

     pure subroutine la_ytprfb(side,trans,direct,storev,m,n,k,l,v,ldv,t,ldt,a, &
               lda,b,ldb,work,ldwork)
        use la_constants_xdp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: direct,side,storev,trans
           integer(ilp),intent(in) :: k,l,lda,ldb,ldt,ldv,ldwork,m,n
           ! Array Arguments
           complex(xdp),intent(inout) :: a(lda,*),b(ldb,*)
           complex(xdp),intent(in) :: t(ldt,*),v(ldv,*)
           complex(xdp),intent(out) :: work(ldwork,*)
        ! ==========================================================================

           ! Local Scalars
           integer(ilp) :: i,j,mp,np,kp
           logical(lk) :: left,forward,column,right,backward,row
           ! Intrinsic Functions
           intrinsic :: conjg
           ! Executable Statements
           ! quick return if possible
           if (m <= 0 .or. n <= 0 .or. k <= 0 .or. l < 0) return
           if (la_lsame(storev,'C')) then
              column = .true.
              row = .false.
           else if (la_lsame(storev,'R')) then
              column = .false.
              row = .true.
           else
              column = .false.
              row = .false.
           end if
           if (la_lsame(side,'L')) then
              left = .true.
              right = .false.
           else if (la_lsame(side,'R')) then
              left = .false.
              right = .true.
           else
              left = .false.
              right = .false.
           end if
           if (la_lsame(direct,'F')) then
              forward = .true.
              backward = .false.
           else if (la_lsame(direct,'B')) then
              forward = .false.
              backward = .true.
           else
              forward = .false.
              backward = .false.
           end if
       ! ---------------------------------------------------------------------------
           if (column .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (m-by-k)
              ! form  h c  or  h**h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a -   t (a + v**h b)  or  a = a -   t**h (a + v**h b)
              ! b = b - v t (a + v**h b)  or  b = b - v t**h (a + v**h b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_ytrmm('L','U','C','N',l,n,cone,v(mp,1),ldv,work,ldwork)

              call la_ygemm('C','N',l,n,m - l,cone,v,ldv,b,ldb,cone,work,ldwork)

              call la_ygemm('C','N',k - l,n,m,cone,v(1,kp),ldv,b,ldb,czero,work( &
                        kp,1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ytrmm('L','U',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_ygemm('N','N',m - l,n,k,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_ygemm('N','N',l,n,k - l,-cone,v(mp,kp),ldv,work(kp,1), &
                        ldwork,cone,b(mp,1),ldb)
              call la_ytrmm('L','U','N','N',l,n,cone,v(mp,1),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (n-by-k)
              ! form  c h or  c h**h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**h
              ! b = b - (a + b v) t v**h  or  b = b - (a + b v) t**h v**h
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_ytrmm('R','U','N','N',m,l,cone,v(np,1),ldv,work,ldwork)

              call la_ygemm('N','N',m,l,n - l,cone,b,ldb,v,ldv,cone,work,ldwork)

              call la_ygemm('N','N',m,k - l,n,cone,b,ldb,v(1,kp),ldv,czero,work( &
                        1,kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ytrmm('R','U',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_ygemm('N','C',m,n - l,k,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_ygemm('N','C',m,l,k - l,-cone,work(1,kp),ldwork,v(np,kp), &
                        ldv,cone,b(1,np),ldb)
              call la_ytrmm('R','U','C','N',m,l,cone,v(np,1),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (m-by-k)
                        ! [ i ]    (k-by-k)
              ! form  h c  or  h**h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a -   t (a + v**h b)  or  a = a -   t**h (a + v**h b)
              ! b = b - v t (a + v**h b)  or  b = b - v t**h (a + v**h b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_ytrmm('L','L','C','N',l,n,cone,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              call la_ygemm('C','N',l,n,m - l,cone,v(mp,kp),ldv,b(mp,1),ldb, &
                        cone,work(kp,1),ldwork)
              call la_ygemm('C','N',k - l,n,m,cone,v,ldv,b,ldb,czero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ytrmm('L','L',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_ygemm('N','N',m - l,n,k,-cone,v(mp,1),ldv,work,ldwork,cone, &
                        b(mp,1),ldb)
              call la_ygemm('N','N',l,n,k - l,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_ytrmm('L','L','N','N',l,n,cone,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (n-by-k)
                        ! [ i ]    (k-by-k)
              ! form  c h  or  c h**h  where  c = [ b a ] (b is m-by-n, a is m-by-k)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**h
              ! b = b - (a + b v) t v**h  or  b = b - (a + b v) t**h v**h
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_ytrmm('R','L','N','N',m,l,cone,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              call la_ygemm('N','N',m,l,n - l,cone,b(1,np),ldb,v(np,kp),ldv, &
                        cone,work(1,kp),ldwork)
              call la_ygemm('N','N',m,k - l,n,cone,b,ldb,v,ldv,czero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ytrmm('R','L',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_ygemm('N','C',m,n - l,k,-cone,work,ldwork,v(np,1),ldv,cone, &
                        b(1,np),ldb)
              call la_ygemm('N','C',m,l,k - l,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_ytrmm('R','L','C','N',m,l,cone,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w**h t w          or  h**h = i - w**h t**h w
              ! a = a -     t (a + v b)  or  a = a -     t**h (a + v b)
              ! b = b - v**h t (a + v b)  or  b = b - v**h t**h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_ytrmm('L','L','N','N',l,n,cone,v(1,mp),ldv,work,ldb)

              call la_ygemm('N','N',l,n,m - l,cone,v,ldv,b,ldb,cone,work,ldwork)

              call la_ygemm('N','N',k - l,n,m,cone,v(kp,1),ldv,b,ldb,czero,work( &
                        kp,1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ytrmm('L','U',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_ygemm('C','N',m - l,n,k,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_ygemm('C','N',l,n,k - l,-cone,v(kp,mp),ldv,work(kp,1), &
                        ldwork,cone,b(mp,1),ldb)
              call la_ytrmm('L','L','C','N',l,n,cone,v(1,mp),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w**h t w            or  h**h = i - w**h t**h w
              ! a = a - (a + b v**h) t      or  a = a - (a + b v**h) t**h
              ! b = b - (a + b v**h) t v    or  b = b - (a + b v**h) t**h v
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_ytrmm('R','L','C','N',m,l,cone,v(1,np),ldv,work,ldwork)

              call la_ygemm('N','C',m,l,n - l,cone,b,ldb,v,ldv,cone,work,ldwork)

              call la_ygemm('N','C',m,k - l,n,cone,b,ldb,v(kp,1),ldv,czero,work( &
                        1,kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ytrmm('R','U',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_ygemm('N','N',m,n - l,k,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_ygemm('N','N',m,l,k - l,-cone,work(1,kp),ldwork,v(kp,np), &
                        ldv,cone,b(1,np),ldb)
              call la_ytrmm('R','L','N','N',m,l,cone,v(1,np),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w**h t w          or  h**h = i - w**h t**h w
              ! a = a -     t (a + v b)  or  a = a -     t**h (a + v b)
              ! b = b - v**h t (a + v b)  or  b = b - v**h t**h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_ytrmm('L','U','N','N',l,n,cone,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              call la_ygemm('N','N',l,n,m - l,cone,v(kp,mp),ldv,b(mp,1),ldb, &
                        cone,work(kp,1),ldwork)
              call la_ygemm('N','N',k - l,n,m,cone,v,ldv,b,ldb,czero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ytrmm('L','L ',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_ygemm('C','N',m - l,n,k,-cone,v(1,mp),ldv,work,ldwork,cone, &
                        b(mp,1),ldb)
              call la_ygemm('C','N',l,n,k - l,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_ytrmm('L','U','C','N',l,n,cone,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**h  where  c = [ b a ] (a is m-by-k, b is m-by-n)
              ! h = i - w**h t w            or  h**h = i - w**h t**h w
              ! a = a - (a + b v**h) t      or  a = a - (a + b v**h) t**h
              ! b = b - (a + b v**h) t v    or  b = b - (a + b v**h) t**h v
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_ytrmm('R','U','C','N',m,l,cone,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              call la_ygemm('N','C',m,l,n - l,cone,b(1,np),ldb,v(kp,np),ldv, &
                        cone,work(1,kp),ldwork)
              call la_ygemm('N','C',m,k - l,n,cone,b,ldb,v,ldv,czero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_ytrmm('R','L',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_ygemm('N','N',m,n - l,k,-cone,work,ldwork,v(1,np),ldv,cone, &
                        b(1,np),ldb)
              call la_ygemm('N','N',m,l,k - l,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_ytrmm('R','U','N','N',m,l,cone,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
           end if
           return
     end subroutine la_ytprfb
#endif
#ifdef LA_WITH_QP
     !> WTPRFB: applies a complex "triangular-pentagonal" block reflector H or its
     !> conjugate transpose H**H to a complex matrix C, which is composed of two
     !> blocks A and B, either from the left or right.

     pure subroutine la_wtprfb(side,trans,direct,storev,m,n,k,l,v,ldv,t,ldt,a, &
               lda,b,ldb,work,ldwork)
        use la_constants_qp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: direct,side,storev,trans
           integer(ilp),intent(in) :: k,l,lda,ldb,ldt,ldv,ldwork,m,n
           ! Array Arguments
           complex(qp),intent(inout) :: a(lda,*),b(ldb,*)
           complex(qp),intent(in) :: t(ldt,*),v(ldv,*)
           complex(qp),intent(out) :: work(ldwork,*)
        ! ==========================================================================

           ! Local Scalars
           integer(ilp) :: i,j,mp,np,kp
           logical(lk) :: left,forward,column,right,backward,row
           ! Intrinsic Functions
           intrinsic :: conjg
           ! Executable Statements
           ! quick return if possible
           if (m <= 0 .or. n <= 0 .or. k <= 0 .or. l < 0) return
           if (la_lsame(storev,'C')) then
              column = .true.
              row = .false.
           else if (la_lsame(storev,'R')) then
              column = .false.
              row = .true.
           else
              column = .false.
              row = .false.
           end if
           if (la_lsame(side,'L')) then
              left = .true.
              right = .false.
           else if (la_lsame(side,'R')) then
              left = .false.
              right = .true.
           else
              left = .false.
              right = .false.
           end if
           if (la_lsame(direct,'F')) then
              forward = .true.
              backward = .false.
           else if (la_lsame(direct,'B')) then
              forward = .false.
              backward = .true.
           else
              forward = .false.
              backward = .false.
           end if
       ! ---------------------------------------------------------------------------
           if (column .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (m-by-k)
              ! form  h c  or  h**h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a -   t (a + v**h b)  or  a = a -   t**h (a + v**h b)
              ! b = b - v t (a + v**h b)  or  b = b - v t**h (a + v**h b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_wtrmm('L','U','C','N',l,n,cone,v(mp,1),ldv,work,ldwork)

              call la_wgemm('C','N',l,n,m - l,cone,v,ldv,b,ldb,cone,work,ldwork)

              call la_wgemm('C','N',k - l,n,m,cone,v(1,kp),ldv,b,ldb,czero,work( &
                        kp,1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_wtrmm('L','U',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_wgemm('N','N',m - l,n,k,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_wgemm('N','N',l,n,k - l,-cone,v(mp,kp),ldv,work(kp,1), &
                        ldwork,cone,b(mp,1),ldb)
              call la_wtrmm('L','U','N','N',l,n,cone,v(mp,1),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i ]    (k-by-k)
                        ! [ v ]    (n-by-k)
              ! form  c h or  c h**h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**h
              ! b = b - (a + b v) t v**h  or  b = b - (a + b v) t**h v**h
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_wtrmm('R','U','N','N',m,l,cone,v(np,1),ldv,work,ldwork)

              call la_wgemm('N','N',m,l,n - l,cone,b,ldb,v,ldv,cone,work,ldwork)

              call la_wgemm('N','N',m,k - l,n,cone,b,ldb,v(1,kp),ldv,czero,work( &
                        1,kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_wtrmm('R','U',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_wgemm('N','C',m,n - l,k,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_wgemm('N','C',m,l,k - l,-cone,work(1,kp),ldwork,v(np,kp), &
                        ldv,cone,b(1,np),ldb)
              call la_wtrmm('R','U','C','N',m,l,cone,v(np,1),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (m-by-k)
                        ! [ i ]    (k-by-k)
              ! form  h c  or  h**h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a -   t (a + v**h b)  or  a = a -   t**h (a + v**h b)
              ! b = b - v t (a + v**h b)  or  b = b - v t**h (a + v**h b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_wtrmm('L','L','C','N',l,n,cone,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              call la_wgemm('C','N',l,n,m - l,cone,v(mp,kp),ldv,b(mp,1),ldb, &
                        cone,work(kp,1),ldwork)
              call la_wgemm('C','N',k - l,n,m,cone,v,ldv,b,ldb,czero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_wtrmm('L','L',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_wgemm('N','N',m - l,n,k,-cone,v(mp,1),ldv,work,ldwork,cone, &
                        b(mp,1),ldb)
              call la_wgemm('N','N',l,n,k - l,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_wtrmm('L','L','N','N',l,n,cone,v(1,kp),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (column .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v ]    (n-by-k)
                        ! [ i ]    (k-by-k)
              ! form  c h  or  c h**h  where  c = [ b a ] (b is m-by-n, a is m-by-k)
              ! h = i - w t w**h          or  h**h = i - w t**h w**h
              ! a = a - (a + b v) t      or  a = a - (a + b v) t**h
              ! b = b - (a + b v) t v**h  or  b = b - (a + b v) t**h v**h
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_wtrmm('R','L','N','N',m,l,cone,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              call la_wgemm('N','N',m,l,n - l,cone,b(1,np),ldb,v(np,kp),ldv, &
                        cone,work(1,kp),ldwork)
              call la_wgemm('N','N',m,k - l,n,cone,b,ldb,v,ldv,czero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_wtrmm('R','L',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_wgemm('N','C',m,n - l,k,-cone,work,ldwork,v(np,1),ldv,cone, &
                        b(1,np),ldb)
              call la_wgemm('N','C',m,l,k - l,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_wtrmm('R','L','C','N',m,l,cone,v(1,kp),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**h c  where  c = [ a ]  (k-by-n)
                                                ! [ b ]  (m-by-n)
              ! h = i - w**h t w          or  h**h = i - w**h t**h w
              ! a = a -     t (a + v b)  or  a = a -     t**h (a + v b)
              ! b = b - v**h t (a + v b)  or  b = b - v**h t**h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(m - l + 1,m)
              kp = min(l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(i,j) = b(m - l + i,j)
                 end do
              end do
              call la_wtrmm('L','L','N','N',l,n,cone,v(1,mp),ldv,work,ldb)

              call la_wgemm('N','N',l,n,m - l,cone,v,ldv,b,ldb,cone,work,ldwork)

              call la_wgemm('N','N',k - l,n,m,cone,v(kp,1),ldv,b,ldb,czero,work( &
                        kp,1),ldwork)
              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_wtrmm('L','U',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_wgemm('C','N',m - l,n,k,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_wgemm('C','N',l,n,k - l,-cone,v(kp,mp),ldv,work(kp,1), &
                        ldwork,cone,b(mp,1),ldb)
              call la_wtrmm('L','L','C','N',l,n,cone,v(1,mp),ldv,work,ldwork)

              do j = 1,n
                 do i = 1,l
                    b(m - l + i,j) = b(m - l + i,j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. forward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ i v ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**h  where  c = [ a b ] (a is m-by-k, b is m-by-n)
              ! h = i - w**h t w            or  h**h = i - w**h t**h w
              ! a = a - (a + b v**h) t      or  a = a - (a + b v**h) t**h
              ! b = b - (a + b v**h) t v    or  b = b - (a + b v**h) t**h v
       ! ---------------------------------------------------------------------------
              np = min(n - l + 1,n)
              kp = min(l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,j) = b(i,n - l + j)
                 end do
              end do
              call la_wtrmm('R','L','C','N',m,l,cone,v(1,np),ldv,work,ldwork)

              call la_wgemm('N','C',m,l,n - l,cone,b,ldb,v,ldv,cone,work,ldwork)

              call la_wgemm('N','C',m,k - l,n,cone,b,ldb,v(kp,1),ldv,czero,work( &
                        1,kp),ldwork)
              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_wtrmm('R','U',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_wgemm('N','N',m,n - l,k,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_wgemm('N','N',m,l,k - l,-cone,work(1,kp),ldwork,v(kp,np), &
                        ldv,cone,b(1,np),ldb)
              call la_wtrmm('R','L','N','N',m,l,cone,v(1,np),ldv,work,ldwork)

              do j = 1,l
                 do i = 1,m
                    b(i,n - l + j) = b(i,n - l + j) - work(i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. left) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-m )
              ! form  h c  or  h**h c  where  c = [ b ]  (m-by-n)
                                                ! [ a ]  (k-by-n)
              ! h = i - w**h t w          or  h**h = i - w**h t**h w
              ! a = a -     t (a + v b)  or  a = a -     t**h (a + v b)
              ! b = b - v**h t (a + v b)  or  b = b - v**h t**h (a + v b)
       ! ---------------------------------------------------------------------------
              mp = min(l + 1,m)
              kp = min(k - l + 1,k)
              do j = 1,n
                 do i = 1,l
                    work(k - l + i,j) = b(i,j)
                 end do
              end do
              call la_wtrmm('L','U','N','N',l,n,cone,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              call la_wgemm('N','N',l,n,m - l,cone,v(kp,mp),ldv,b(mp,1),ldb, &
                        cone,work(kp,1),ldwork)
              call la_wgemm('N','N',k - l,n,m,cone,v,ldv,b,ldb,czero,work,ldwork)

              do j = 1,n
                 do i = 1,k
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_wtrmm('L','L ',trans,'N',k,n,cone,t,ldt,work,ldwork)
              do j = 1,n
                 do i = 1,k
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_wgemm('C','N',m - l,n,k,-cone,v(1,mp),ldv,work,ldwork,cone, &
                        b(mp,1),ldb)
              call la_wgemm('C','N',l,n,k - l,-cone,v,ldv,work,ldwork,cone,b,ldb)

              call la_wtrmm('L','U','C','N',l,n,cone,v(kp,1),ldv,work(kp,1), &
                        ldwork)
              do j = 1,n
                 do i = 1,l
                    b(i,j) = b(i,j) - work(k - l + i,j)
                 end do
              end do
       ! ---------------------------------------------------------------------------
           else if (row .and. backward .and. right) then
       ! ---------------------------------------------------------------------------
              ! let  w =  [ v i ] ( i is k-by-k, v is k-by-n )
              ! form  c h  or  c h**h  where  c = [ b a ] (a is m-by-k, b is m-by-n)
              ! h = i - w**h t w            or  h**h = i - w**h t**h w
              ! a = a - (a + b v**h) t      or  a = a - (a + b v**h) t**h
              ! b = b - (a + b v**h) t v    or  b = b - (a + b v**h) t**h v
       ! ---------------------------------------------------------------------------
              np = min(l + 1,n)
              kp = min(k - l + 1,k)
              do j = 1,l
                 do i = 1,m
                    work(i,k - l + j) = b(i,j)
                 end do
              end do
              call la_wtrmm('R','U','C','N',m,l,cone,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              call la_wgemm('N','C',m,l,n - l,cone,b(1,np),ldb,v(kp,np),ldv, &
                        cone,work(1,kp),ldwork)
              call la_wgemm('N','C',m,k - l,n,cone,b,ldb,v,ldv,czero,work,ldwork)

              do j = 1,k
                 do i = 1,m
                    work(i,j) = work(i,j) + a(i,j)
                 end do
              end do
              call la_wtrmm('R','L',trans,'N',m,k,cone,t,ldt,work,ldwork)
              do j = 1,k
                 do i = 1,m
                    a(i,j) = a(i,j) - work(i,j)
                 end do
              end do
              call la_wgemm('N','N',m,n - l,k,-cone,work,ldwork,v(1,np),ldv,cone, &
                        b(1,np),ldb)
              call la_wgemm('N','N',m,l,k - l,-cone,work,ldwork,v,ldv,cone,b,ldb)

              call la_wtrmm('R','U','N','N',m,l,cone,v(kp,1),ldv,work(1,kp), &
                        ldwork)
              do j = 1,l
                 do i = 1,m
                    b(i,j) = b(i,j) - work(i,k - l + j)
                 end do
              end do
           end if
           return
     end subroutine la_wtprfb
#endif

     !> CUNG2R: generates an m by n complex matrix Q with orthonormal columns,
     !> which is defined as the first n columns of a product of k elementary
     !> reflectors of order m
     !> Q  =  H(1) H(2) . . . H(k)
     !> as returned by CGEQRF.

     pure subroutine la_cung2r(m,n,k,a,lda,tau,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,lda,m,n
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(in) :: tau(*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,l
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input arguments
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0 .or. n > m) then
              info = -2
           else if (k < 0 .or. k > n) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('CUNG2R',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) return
           ! initialise columns k+1:n to columns of the unit matrix
           do j = k + 1,n
              do l = 1,m
                 a(l,j) = czero
              end do
              a(j,j) = cone
           end do
           do i = k,1,-1
              ! apply h(i) to a(i:m,i:n) from the left
              if (i < n) then
                 a(i,i) = cone
                 call la_clarf('LEFT',m - i + 1,n - i,a(i,i),1,tau(i),a(i,i + 1),lda, &
                           work)
              end if
              if (i < m) call la_cscal(m - i,-tau(i),a(i + 1,i),1)
              a(i,i) = cone - tau(i)
              ! set a(1:i-1,i) to czero
              do l = 1,i - 1
                 a(l,i) = czero
              end do
           end do
           return
     end subroutine la_cung2r
