     !> CUNGQR: generates an M-by-N complex matrix Q with orthonormal columns,
     !> which is defined as the first N columns of a product of K elementary
     !> reflectors of order M
     !> Q  =  H(1) H(2) . . . H(k)
     !> as returned by CGEQRF.

     pure subroutine la_cungqr(m,n,k,a,lda,tau,work,lwork,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,lda,lwork,m,n
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(in) :: tau(*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: i,ib,iinfo,iws,j,ki,kk,l,ldwork,lwkopt,nb,nbmin,nx
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           nb = la_ilaenv(1,'CUNGQR',' ',m,n,k,-1)
           lwkopt = max(1,n)*nb
           work(1) = lwkopt
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < 0 .or. n > m) then
              info = -2
           else if (k < 0 .or. k > n) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           else if (lwork < max(1,n) .and. .not. lquery) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('CUNGQR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = 1
              return
           end if
           nbmin = 2
           nx = 0
           iws = n
           if (nb > 1 .and. nb < k) then
              ! determine when to cross over from blocked to unblocked code.
              nx = max(0,la_ilaenv(3,'CUNGQR',' ',m,n,k,-1))
              if (nx < k) then
                 ! determine if workspace is large enough for blocked code.
                 ldwork = n
                 iws = ldwork*nb
                 if (lwork < iws) then
                    ! not enough workspace to use optimal nb:  reduce nb and
                    ! determine the minimum value of nb.
                    nb = lwork/ldwork
                    nbmin = max(2,la_ilaenv(2,'CUNGQR',' ',m,n,k,-1))
                 end if
              end if
           end if
           if (nb >= nbmin .and. nb < k .and. nx < k) then
              ! use blocked code after the last block.
              ! the first kk columns are handled by the block method.
              ki = ((k - nx - 1)/nb)*nb
              kk = min(k,ki + nb)
              ! set a(1:kk,kk+1:n) to czero.
              do j = kk + 1,n
                 do i = 1,kk
                    a(i,j) = czero
                 end do
              end do
           else
              kk = 0
           end if
           ! use unblocked code for the last or only block.
           if (kk < n) call la_cung2r(m - kk,n - kk,k - kk,a(kk + 1,kk + 1),lda,tau(kk + 1),work, &
                      iinfo)
           if (kk > 0) then
              ! use blocked code
              do i = ki + 1,1,-nb
                 ib = min(nb,k - i + 1)
                 if (i + ib <= n) then
                    ! form the triangular factor of the block reflector
                    ! h = h(i) h(i+1) . . . h(i+ib-1)
                    call la_clarft('FORWARD','COLUMNWISE',m - i + 1,ib,a(i,i),lda,tau(i &
                              ),work,ldwork)
                    ! apply h to a(i:m,i+ib:n) from the left
                    call la_clarfb('LEFT','NO TRANSPOSE','FORWARD','COLUMNWISE',m - i + 1,n - &
                    i - ib + 1,ib,a(i,i),lda,work,ldwork,a(i,i + ib),lda,work(ib + 1), &
                              ldwork)
                 end if
                 ! apply h to rows i:m of current block
                 call la_cung2r(m - i + 1,ib,ib,a(i,i),lda,tau(i),work,iinfo)
                 ! set rows 1:i-1 of current block to czero
                 do j = i,i + ib - 1
                    do l = 1,i - 1
                       a(l,j) = czero
                    end do
                 end do
              end do
           end if
           work(1) = iws
           return
     end subroutine la_cungqr
     !> ZUNGQR: generates an M-by-N complex matrix Q with orthonormal columns,
