        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,lda,m,n
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(in) :: tau(*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,ii,j,l
           ! Intrinsic Functions
           intrinsic :: conjg,max
           ! Executable Statements
           ! test the input arguments
           info = 0
           if (m < 0) then
              info = -1
           else if (n < m) then
              info = -2
           else if (k < 0 .or. k > m) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('CUNGR2',-info)
              return
           end if
           ! quick return if possible
           if (m <= 0) return
           if (k < m) then
              ! initialise rows 1:m-k to rows of the unit matrix
              do j = 1,n
                 do l = 1,m - k
                    a(l,j) = czero
                 end do
                 if (j > n - m .and. j <= n - k) a(m - n + j,j) = cone
              end do
           end if
           do i = 1,k
              ii = m - k + i
              ! apply h(i)**h to a(1:m-k+i,1:n-k+i) from the right
              call la_clacgv(n - m + ii - 1,a(ii,1),lda)
              a(ii,n - m + ii) = cone
              call la_clarf('RIGHT',ii - 1,n - m + ii,a(ii,1),lda,conjg(tau(i)),a,lda, &
                         work)
              call la_cscal(n - m + ii - 1,-tau(i),a(ii,1),lda)
              call la_clacgv(n - m + ii - 1,a(ii,1),lda)
              a(ii,n - m + ii) = cone - conjg(tau(i))
              ! set a(m-k+i,n-k+i+1:n) to czero
              do l = n - m + ii + 1,n
                 a(ii,l) = czero
              end do
           end do
           return
