              ! the last kk rows are handled by the block method.
              kk = min(k, ((k - nx + nb - 1)/nb)*nb)
              ! set a(1:m-kk,n-kk+1:n) to czero.
              do j = n - kk + 1,n
                 do i = 1,m - kk
                    a(i,j) = czero
                 end do
              end do
           else
              kk = 0
           end if
           ! use unblocked code for the first or only block.
           call la_cungr2(m - kk,n - kk,k - kk,a,lda,tau,work,iinfo)
           if (kk > 0) then
              ! use blocked code
              do i = k - kk + 1,k,nb
                 ib = min(nb,k - i + 1)
                 ii = m - k + i
                 if (ii > 1) then
                    ! form the triangular factor of the block reflector
                    ! h = h(i+ib-1) . . . h(i+1) h(i)
                    call la_clarft('BACKWARD','ROWWISE',n - k + i + ib - 1,ib,a(ii,1),lda, &
                              tau(i),work,ldwork)
                    ! apply h**h to a(1:m-k+i-1,1:n-k+i+ib-1) from the right
                    call la_clarfb('RIGHT','CONJUGATE TRANSPOSE','BACKWARD','ROWWISE',ii - &
                    1,n - k + i + ib - 1,ib,a(ii,1),lda,work,ldwork,a,lda,work(ib + 1),ldwork)

                 end if
                 ! apply h**h to columns 1:n-k+i+ib-1 of current block
                 call la_cungr2(ib,n - k + i + ib - 1,ib,a(ii,1),lda,tau(i),work,iinfo)

                 ! set columns n-k+i+ib:n of current block to czero
                 do l = n - k + i + ib,n
                    do j = ii,ii + ib - 1
                       a(j,l) = czero
                    end do
                 end do
              end do
           end if
           work(1) = iws
           return
     end subroutine la_cungrq
     !> ZUNGRQ: generates an M-by-N complex matrix Q with orthonormal rows,
     !> which is defined as the last M rows of a product of K elementary
     !> reflectors of order N
     !> Q  =  H(1)**H H(2)**H . . . H(k)**H
     !> as returned by ZGERQF.

     pure subroutine la_zungrq(m,n,k,a,lda,tau,work,lwork,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,lda,lwork,m,n
           ! Array Arguments
           complex(dp),intent(inout) :: a(lda,*)
           complex(dp),intent(in) :: tau(*)
           complex(dp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: i,ib,ii,iinfo,iws,j,kk,l,ldwork,lwkopt,nb,nbmin,nx
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < m) then
              info = -2
           else if (k < 0 .or. k > m) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           end if
           if (info == 0) then
              if (m <= 0) then
                 lwkopt = 1
              else
                 nb = la_ilaenv(1,'ZUNGRQ',' ',m,n,k,-1)
                 lwkopt = m*nb
              end if
              work(1) = lwkopt
              if (lwork < max(1,m) .and. .not. lquery) then
                 info = -8
              end if
           end if
           if (info /= 0) then
              call la_xerbla('ZUNGRQ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m <= 0) then
              return
           end if
           nbmin = 2
           nx = 0
           iws = m
           if (nb > 1 .and. nb < k) then
              ! determine when to cross over from blocked to unblocked code.
              nx = max(0,la_ilaenv(3,'ZUNGRQ',' ',m,n,k,-1))
              if (nx < k) then
                 ! determine if workspace is large enough for blocked code.
                 ldwork = m
                 iws = ldwork*nb
                 if (lwork < iws) then
                    ! not enough workspace to use optimal nb:  reduce nb and
                    ! determine the minimum value of nb.
                    nb = lwork/ldwork
                    nbmin = max(2,la_ilaenv(2,'ZUNGRQ',' ',m,n,k,-1))
                 end if
              end if
           end if
           if (nb >= nbmin .and. nb < k .and. nx < k) then
              ! use blocked code after the first block.
              ! the last kk rows are handled by the block method.
              kk = min(k, ((k - nx + nb - 1)/nb)*nb)
              ! set a(1:m-kk,n-kk+1:n) to czero.
              do j = n - kk + 1,n
                 do i = 1,m - kk
                    a(i,j) = czero
                 end do
              end do
           else
              kk = 0
           end if
           ! use unblocked code for the first or only block.
           call la_zungr2(m - kk,n - kk,k - kk,a,lda,tau,work,iinfo)
           if (kk > 0) then
              ! use blocked code
              do i = k - kk + 1,k,nb
                 ib = min(nb,k - i + 1)
                 ii = m - k + i
                 if (ii > 1) then
                    ! form the triangular factor of the block reflector
                    ! h = h(i+ib-1) . . . h(i+1) h(i)
                    call la_zlarft('BACKWARD','ROWWISE',n - k + i + ib - 1,ib,a(ii,1),lda, &
                              tau(i),work,ldwork)
                    ! apply h**h to a(1:m-k+i-1,1:n-k+i+ib-1) from the right
                    call la_zlarfb('RIGHT','CONJUGATE TRANSPOSE','BACKWARD','ROWWISE',ii - &
                    1,n - k + i + ib - 1,ib,a(ii,1),lda,work,ldwork,a,lda,work(ib + 1),ldwork)

                 end if
                 ! apply h**h to columns 1:n-k+i+ib-1 of current block
                 call la_zungr2(ib,n - k + i + ib - 1,ib,a(ii,1),lda,tau(i),work,iinfo)

                 ! set columns n-k+i+ib:n of current block to czero
                 do l = n - k + i + ib,n
                    do j = ii,ii + ib - 1
                       a(j,l) = czero
                    end do
                 end do
              end do
           end if
           work(1) = iws
           return
     end subroutine la_zungrq
