                 taui = tau(i)
              end if
              call la_clacgv(nq - k + i - 1,a(i,1),lda)
              aii = a(i,nq - k + i)
              a(i,nq - k + i) = cone
              call la_clarf(side,mi,ni,a(i,1),lda,taui,c,ldc,work)
              a(i,nq - k + i) = aii
              call la_clacgv(nq - k + i - 1,a(i,1),lda)
           end do
           return
     end subroutine la_cunmr2
