     !> CGEMQRT: overwrites the general complex M-by-N matrix C with
     !> SIDE = 'L'     SIDE = 'R'
     !> TRANS = 'N':      Q C            C Q
     !> TRANS = 'C':    Q**H C            C Q**H
     !> where Q is a complex orthogonal matrix defined as the product of K
     !> elementary reflectors:
     !> Q = H(1) H(2) . . . H(K) = I - V T V**H
     !> generated using the compact WY representation as returned by CGEQRT.
     !> Q is of order M if SIDE = 'L' and of order N  if SIDE = 'R'.

     pure subroutine la_cgemqrt(side,trans,m,n,k,nb,v,ldv,t,ldt,c,ldc,work,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: side,trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,ldv,ldc,m,n,nb,ldt
           ! Array Arguments
           complex(sp),intent(in) :: v(ldv,*),t(ldt,*)
           complex(sp),intent(inout) :: c(ldc,*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: left,right,tran,notran
           integer(ilp) :: i,ib,ldwork,kf,q
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! Test The Input Arguments
           info = 0
           left = la_lsame(side,'L')
           right = la_lsame(side,'R')
           tran = la_lsame(trans,'C')
           notran = la_lsame(trans,'N')
           if (left) then
              ldwork = max(1,n)
              q = m
           else if (right) then
              ldwork = max(1,m)
              q = n
           end if
           if (.not. left .and. .not. right) then
              info = -1
           else if (.not. tran .and. .not. notran) then
              info = -2
           else if (m < 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (k < 0 .or. k > q) then
              info = -5
           else if (nb < 1 .or. (nb > k .and. k > 0)) then
              info = -6
           else if (ldv < max(1,q)) then
              info = -8
           else if (ldt < nb) then
              info = -10
           else if (ldc < max(1,m)) then
              info = -12
           end if
           if (info /= 0) then
              call la_xerbla('CGEMQRT',-info)
              return
           end if
           ! Quick Return If Possible
           if (m == 0 .or. n == 0 .or. k == 0) return
           if (left .and. tran) then
              do i = 1,k,nb
                 ib = min(nb,k - i + 1)
                 call la_clarfb('L','C','F','C',m - i + 1,n,ib,v(i,i),ldv,t(1,i), &
                           ldt,c(i,1),ldc,work,ldwork)
              end do
           else if (right .and. notran) then
              do i = 1,k,nb
                 ib = min(nb,k - i + 1)
                 call la_clarfb('R','N','F','C',m,n - i + 1,ib,v(i,i),ldv,t(1,i), &
                           ldt,c(1,i),ldc,work,ldwork)
              end do
           else if (left .and. notran) then
              kf = ((k - 1)/nb)*nb + 1
              do i = kf,1,-nb
                 ib = min(nb,k - i + 1)
                 call la_clarfb('L','N','F','C',m - i + 1,n,ib,v(i,i),ldv,t(1,i), &
                           ldt,c(i,1),ldc,work,ldwork)
              end do
           else if (right .and. tran) then
              kf = ((k - 1)/nb)*nb + 1
              do i = kf,1,-nb
                 ib = min(nb,k - i + 1)
                 call la_clarfb('R','C','F','C',m,n - i + 1,ib,v(i,i),ldv,t(1,i), &
                           ldt,c(1,i),ldc,work,ldwork)
              end do
           end if
           return
     end subroutine la_cgemqrt
