     !> CGEQR2: computes a QR factorization of a complex m-by-n matrix A:
     !> A = Q * ( R ),
     !> ( 0 )
     !> where:
     !> Q is a m-by-m orthogonal matrix;
     !> R is an upper-triangular n-by-n matrix;
     !> 0 is a (m-n)-by-n zero matrix, if m > n.

     pure subroutine la_cgeqr2(m,n,a,lda,tau,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: tau(*),work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,k
           complex(sp) :: alpha
           ! Intrinsic Functions
           intrinsic :: conjg,max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('CGEQR2',-info)
              return
           end if
           k = min(m,n)
           do i = 1,k
              ! generate elementary reflector h(i) to annihilate a(i+1:m,i)
              call la_clarfg(m - i + 1,a(i,i),a(min(i + 1,m),i),1,tau(i))
              if (i < n) then
                 ! apply h(i)**h to a(i:m,i+1:n) from the left
                 alpha = a(i,i)
                 a(i,i) = cone
                 call la_clarf('LEFT',m - i + 1,n - i,a(i,i),1,conjg(tau(i)),a(i,i + 1 &
                           ),lda,work)
                 a(i,i) = alpha
              end if
           end do
           return
     end subroutine la_cgeqr2
