           nb = la_ilaenv(1,'CGEQRF',' ',m,n,-1,-1)
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           else if (.not. lquery) then
              if (lwork <= 0 .or. (m > 0 .and. lwork < max(1,n))) info = -7
           end if
