              if (k == 0) then
                 lwkopt = 1
              else
                 lwkopt = n*nb
              end if
              work(1) = lwkopt
              return
           end if
           ! quick return if possible
           if (k == 0) then
              work(1) = 1
              return
           end if
           nbmin = 2
           nx = 0
           iws = n
           if (nb > 1 .and. nb < k) then
              ! determine when to cross over from blocked to unblocked code.
              nx = max(0,la_ilaenv(3,'CGEQRF',' ',m,n,-1,-1))
