              call la_ctrmm('L','L','C','U',n1,n2,cone,a,lda,t(1,j1),ldt)

              call la_cgemm('C','N',n1,n2,m - n1,cone,a(j1,1),lda,a(j1,j1),lda, &
                        cone,t(1,j1),ldt)
