     !> CGERQ2: computes an RQ factorization of a complex m by n matrix A:
     !> A = R * Q.

     pure subroutine la_cgerq2(m,n,a,lda,tau,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: tau(*),work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,k
           complex(sp) :: alpha
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('CGERQ2',-info)
              return
           end if
           k = min(m,n)
           do i = k,1,-1
              ! generate elementary reflector h(i) to annihilate
              ! a(m-k+i,1:n-k+i-1)
              call la_clacgv(n - k + i,a(m - k + i,1),lda)
              alpha = a(m - k + i,n - k + i)
              call la_clarfg(n - k + i,alpha,a(m - k + i,1),lda,tau(i))
              ! apply h(i) to a(1:m-k+i-1,1:n-k+i) from the right
              a(m - k + i,n - k + i) = cone
              call la_clarf('RIGHT',m - k + i - 1,n - k + i,a(m - k + i,1),lda,tau(i),a,lda, &
                        work)
              a(m - k + i,n - k + i) = alpha
              call la_clacgv(n - k + i - 1,a(m - k + i,1),lda)
           end do
           return
     end subroutine la_cgerq2
