              ! apply h(i) to a(1:m-k+i-1,1:n-k+i) from the right
              a(m - k + i,n - k + i) = cone
              call la_ylarf('RIGHT',m - k + i - 1,n - k + i,a(m - k + i,1),lda,tau(i),a,lda, &
                        work)
              a(m - k + i,n - k + i) = alpha
              call la_ylacgv(n - k + i - 1,a(m - k + i,1),lda)
           end do
           return
     end subroutine la_ygerq2
