              info = -8
           else if (lwork < max(1,m,p,n) .and. .not. lquery) then
              info = -11
           end if
           if (info /= 0) then
              call la_xerbla('WGGRQF',-info)
              return
           else if (lquery) then
              return
           end if
           ! rq factorization of m-by-n matrix a: a = r*q
           call la_wgerqf(m,n,a,lda,taua,work,lwork,info)
           lopt = real(work(1),KIND=qp)
           ! update b := b*q**h
           call la_wunmrq('RIGHT','CONJUGATE TRANSPOSE',p,n,min(m,n),a(max(1,m - n + 1 &
                     ),1),lda,taua,b,ldb,work,lwork,info)
           lopt = max(lopt,int(work(1),KIND=ilp))
           ! qr factorization of p-by-n matrix b: b = z*t
           call la_wgeqrf(p,n,b,ldb,taub,work,lwork,info)
           work(1) = max(lopt,int(work(1),KIND=ilp))
           return
     end subroutine la_wggrqf
#endif

     !> CLAQP2: computes a QR factorization with column pivoting of
     !> the block A(OFFSET+1:M,1:N).
     !> The block A(1:OFFSET,1:N) is accordingly pivoted, but not factorized.

     pure subroutine la_claqp2(m,n,offset,a,lda,jpvt,tau,vn1,vn2,work)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: lda,m,n,offset
           ! Array Arguments
           integer(ilp),intent(inout) :: jpvt(*)
           real(sp),intent(inout) :: vn1(*),vn2(*)
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: tau(*),work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,itemp,j,mn,offpi,pvt
           real(sp) :: temp,temp2,tol3z
           complex(sp) :: aii
           ! Intrinsic Functions
           intrinsic :: abs,conjg,max,min,sqrt
           ! Executable Statements
           mn = min(m - offset,n)
           tol3z = sqrt(la_slamch('EPSILON'))
           ! compute factorization.
           loop_20: do i = 1,mn
              offpi = offset + i
              ! determine ith pivot column and swap if necessary.
              pvt = (i - 1) + la_isamax(n - i + 1,vn1(i),1)
              if (pvt /= i) then
                 call la_cswap(m,a(1,pvt),1,a(1,i),1)
                 itemp = jpvt(pvt)
                 jpvt(pvt) = jpvt(i)
                 jpvt(i) = itemp
                 vn1(pvt) = vn1(i)
                 vn2(pvt) = vn2(i)
              end if
              ! generate elementary reflector h(i).
              if (offpi < m) then
                 call la_clarfg(m - offpi + 1,a(offpi,i),a(offpi + 1,i),1,tau(i))

              else
                 call la_clarfg(1,a(m,i),a(m,i),1,tau(i))
              end if
              if (i < n) then
                 ! apply h(i)**h to a(offset+i:m,i+1:n) from the left.
                 aii = a(offpi,i)
                 a(offpi,i) = cone
                 call la_clarf('LEFT',m - offpi + 1,n - i,a(offpi,i),1,conjg(tau(i)),a( &
                            offpi,i + 1),lda,work(1))
                 a(offpi,i) = aii
              end if
              ! update partial column norms.
              do j = i + 1,n
                 if (vn1(j) /= zero) then
                    ! note: the following 4 lines follow from the analysis in
                    ! lapack working note 176.
                    temp = one - (abs(a(offpi,j))/vn1(j))**2
                    temp = max(temp,zero)
                    temp2 = temp*(vn1(j)/vn2(j))**2
                    if (temp2 <= tol3z) then
                       if (offpi < m) then
                          vn1(j) = la_scnrm2(m - offpi,a(offpi + 1,j),1)
                          vn2(j) = vn1(j)
                       else
                          vn1(j) = zero
                          vn2(j) = zero
                       end if
                    else
                       vn1(j) = vn1(j)*sqrt(temp)
                    end if
                 end if
              end do
           end do loop_20
           return
     end subroutine la_claqp2
