     !> CTPMQRT: applies a complex orthogonal matrix Q obtained from a
     !> "triangular-pentagonal" complex block reflector H to a general
     !> complex matrix C, which consists of two blocks A and B.

     pure subroutine la_ctpmqrt(side,trans,m,n,k,l,nb,v,ldv,t,ldt,a,lda,b,ldb, &
               work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: side,trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,ldv,lda,ldb,m,n,l,nb,ldt
           ! Array Arguments
           complex(sp),intent(in) :: v(ldv,*),t(ldt,*)
           complex(sp),intent(inout) :: a(lda,*),b(ldb,*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: left,right,tran,notran
           integer(ilp) :: i,ib,mb,lb,kf,ldaq,ldvq
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! Test The Input Arguments
           info = 0
           left = la_lsame(side,'L')
           right = la_lsame(side,'R')
           tran = la_lsame(trans,'C')
           notran = la_lsame(trans,'N')
           if (left) then
              ldvq = max(1,m)
              ldaq = max(1,k)
           else if (right) then
              ldvq = max(1,n)
              ldaq = max(1,m)
           end if
           if (.not. left .and. .not. right) then
              info = -1
           else if (.not. tran .and. .not. notran) then
              info = -2
           else if (m < 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (k < 0) then
              info = -5
           else if (l < 0 .or. l > k) then
              info = -6
           else if (nb < 1 .or. (nb > k .and. k > 0)) then
              info = -7
           else if (ldv < ldvq) then
              info = -9
           else if (ldt < nb) then
              info = -11
           else if (lda < ldaq) then
              info = -13
           else if (ldb < max(1,m)) then
              info = -15
           end if
           if (info /= 0) then
              call la_xerbla('CTPMQRT',-info)
              return
           end if
           ! Quick Return If Possible
           if (m == 0 .or. n == 0 .or. k == 0) return
           if (left .and. tran) then
              do i = 1,k,nb
                 ib = min(nb,k - i + 1)
                 mb = min(m - l + i + ib - 1,m)
                 if (i >= l) then
                    lb = 0
                 else
                    lb = mb - m + l - i + 1
                 end if
                 call la_ctprfb('L','C','F','C',mb,n,ib,lb,v(1,i),ldv,t(1,i), &
                           ldt,a(i,1),lda,b,ldb,work,ib)
              end do
           else if (right .and. notran) then
              do i = 1,k,nb
                 ib = min(nb,k - i + 1)
                 mb = min(n - l + i + ib - 1,n)
                 if (i >= l) then
                    lb = 0
                 else
                    lb = mb - n + l - i + 1
                 end if
                 call la_ctprfb('R','N','F','C',m,mb,ib,lb,v(1,i),ldv,t(1,i), &
                           ldt,a(1,i),lda,b,ldb,work,m)
              end do
           else if (left .and. notran) then
              kf = ((k - 1)/nb)*nb + 1
              do i = kf,1,-nb
                 ib = min(nb,k - i + 1)
                 mb = min(m - l + i + ib - 1,m)
                 if (i >= l) then
                    lb = 0
                 else
                    lb = mb - m + l - i + 1
                 end if
                 call la_ctprfb('L','N','F','C',mb,n,ib,lb,v(1,i),ldv,t(1,i), &
                           ldt,a(i,1),lda,b,ldb,work,ib)
              end do
           else if (right .and. tran) then
              kf = ((k - 1)/nb)*nb + 1
              do i = kf,1,-nb
                 ib = min(nb,k - i + 1)
                 mb = min(n - l + i + ib - 1,n)
                 if (i >= l) then
                    lb = 0
                 else
                    lb = mb - n + l - i + 1
                 end if
                 call la_ctprfb('R','C','F','C',m,mb,ib,lb,v(1,i),ldv,t(1,i), &
                           ldt,a(1,i),lda,b,ldb,work,m)
              end do
           end if
           return
     end subroutine la_ctpmqrt
