              end do
           else if (left .and. notran) then
              kf = ((k - 1)/nb)*nb + 1
              do i = kf,1,-nb
                 ib = min(nb,k - i + 1)
                 mb = min(m - l + i + ib - 1,m)
                 if (i >= l) then
                    lb = 0
                 else
                    lb = mb - m + l - i + 1
                 end if
                 call la_ytprfb('L','N','F','C',mb,n,ib,lb,v(1,i),ldv,t(1,i), &
                           ldt,a(i,1),lda,b,ldb,work,ib)
              end do
           else if (right .and. tran) then
              kf = ((k - 1)/nb)*nb + 1
              do i = kf,1,-nb
                 ib = min(nb,k - i + 1)
                 mb = min(n - l + i + ib - 1,n)
                 if (i >= l) then
                    lb = 0
                 else
                    lb = mb - n + l - i + 1
                 end if
                 call la_ytprfb('R','C','F','C',m,mb,ib,lb,v(1,i),ldv,t(1,i), &
                           ldt,a(1,i),lda,b,ldb,work,m)
              end do
           end if
