     !> CGEQP3: computes a QR factorization with column pivoting of a
     !> matrix A:  A*P = Q*R  using Level 3 BLAS.

     pure subroutine la_cgeqp3(m,n,a,lda,jpvt,tau,work,lwork,rwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,lwork,m,n
           ! Array Arguments
           integer(ilp),intent(inout) :: jpvt(*)
           real(sp),intent(out) :: rwork(*)
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: tau(*),work(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: inb = 1
           integer(ilp),parameter :: inbmin = 2
           integer(ilp),parameter :: ixover = 3

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: fjb,iws,j,jb,lwkopt,minmn,minws,na,nb,nbmin,nfxd,nx,sm, &
                     sminmn,sn,topbmn
           ! Intrinsic Functions
           intrinsic :: int,max,min
           ! Executable Statements
           ! test input arguments
        ! ====================
           info = 0
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info == 0) then
              minmn = min(m,n)
              if (minmn == 0) then
                 iws = 1
                 lwkopt = 1
              else
                 iws = n + 1
                 nb = la_ilaenv(inb,'CGEQRF',' ',m,n,-1,-1)
                 lwkopt = (n + 1)*nb
              end if
              work(1) = cmplx(lwkopt,KIND=sp)
              if ((lwork < iws) .and. .not. lquery) then
                 info = -8
              end if
           end if
           if (info /= 0) then
              call la_xerbla('CGEQP3',-info)
              return
           else if (lquery) then
              return
           end if
           ! move initial columns up front.
           nfxd = 1
           do j = 1,n
              if (jpvt(j) /= 0) then
                 if (j /= nfxd) then
                    call la_cswap(m,a(1,j),1,a(1,nfxd),1)
                    jpvt(j) = jpvt(nfxd)
                    jpvt(nfxd) = j
                 else
                    jpvt(j) = j
                 end if
                 nfxd = nfxd + 1
              else
                 jpvt(j) = j
              end if
           end do
           nfxd = nfxd - 1
           ! factorize fixed columns
        ! =======================
           ! compute the qr factorization of fixed columns and update
           ! remaining columns.
           if (nfxd > 0) then
              na = min(m,nfxd)
      ! cc      call la_cgeqr2( m, na, a, lda, tau, work, info )
              call la_cgeqrf(m,na,a,lda,tau,work,lwork,info)
              iws = max(iws,int(work(1),KIND=ilp))
              if (na < n) then
      ! cc         call la_cunm2r( 'left', 'conjugate transpose', m, n-na,
      ! cc  $                   na, a, lda, tau, a( 1, na+1 ), lda, work,
      ! cc  $                   info )
                 call la_cunmqr('LEFT','CONJUGATE TRANSPOSE',m,n - na,na,a,lda,tau,a(1, &
                            na + 1),lda,work,lwork,info)
                 iws = max(iws,int(work(1),KIND=ilp))
              end if
           end if
           ! factorize free columns
        ! ======================
           if (nfxd < minmn) then
              sm = m - nfxd
              sn = n - nfxd
              sminmn = minmn - nfxd
              ! determine the block size.
              nb = la_ilaenv(inb,'CGEQRF',' ',sm,sn,-1,-1)
              nbmin = 2
              nx = 0
              if ((nb > 1) .and. (nb < sminmn)) then
                 ! determine when to cross over from blocked to unblocked code.
                 nx = max(0,la_ilaenv(ixover,'CGEQRF',' ',sm,sn,-1,-1))
                 if (nx < sminmn) then
                    ! determine if workspace is large enough for blocked code.
                    minws = (sn + 1)*nb
                    iws = max(iws,minws)
                    if (lwork < minws) then
                       ! not enough workspace to use optimal nb: reduce nb and
                       ! determine the minimum value of nb.
                       nb = lwork/(sn + 1)
                       nbmin = max(2,la_ilaenv(inbmin,'CGEQRF',' ',sm,sn,-1,-1))

                    end if
                 end if
              end if
              ! initialize partial column norms. the first n elements of work
              ! store the exact column norms.
              do j = nfxd + 1,n
                 rwork(j) = la_scnrm2(sm,a(nfxd + 1,j),1)
                 rwork(n + j) = rwork(j)
              end do
              if ((nb >= nbmin) .and. (nb < sminmn) .and. (nx < sminmn)) then
                 ! use blocked code initially.
                 j = nfxd + 1
                 ! compute factorization: while loop.
                 topbmn = minmn - nx
