                 if (j <= topbmn) then
                    jb = min(nb,topbmn - j + 1)
                    ! factorize jb columns among columns j:n.
                    call la_claqps(m,n - j + 1,j - 1,jb,fjb,a(1,j),lda,jpvt(j),tau(j) &
                              ,rwork(j),rwork(n + j),work(1),work(jb + 1),n - j + 1)
                    j = j + fjb
                    go to 30
                 end if
              else
                 j = nfxd + 1
              end if
              ! use unblocked code to factor the last or only block.
              if (j <= minmn) call la_claqp2(m,n - j + 1,j - 1,a(1,j),lda,jpvt(j),tau(j), &
                         rwork(j),rwork(n + j),work(1))
           end if
           work(1) = cmplx(lwkopt,KIND=sp)
           return
