           complex(dp),intent(out) :: tau(*),work(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: inb = 1
           integer(ilp),parameter :: inbmin = 2
           integer(ilp),parameter :: ixover = 3

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: fjb,iws,j,jb,lwkopt,minmn,minws,na,nb,nbmin,nfxd,nx,sm, &
                     sminmn,sn,topbmn
           ! Intrinsic Functions
           intrinsic :: int,max,min
           ! Executable Statements
           ! test input arguments
        ! ====================
           info = 0
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info == 0) then
              minmn = min(m,n)
              if (minmn == 0) then
                 iws = 1
                 lwkopt = 1
              else
                 iws = n + 1
                 nb = la_ilaenv(inb,'ZGEQRF',' ',m,n,-1,-1)
                 lwkopt = (n + 1)*nb
              end if
              work(1) = cmplx(lwkopt,KIND=dp)
              if ((lwork < iws) .and. .not. lquery) then
                 info = -8
              end if
           end if
           if (info /= 0) then
              call la_xerbla('ZGEQP3',-info)
              return
           else if (lquery) then
              return
           end if
           ! move initial columns up front.
           nfxd = 1
           do j = 1,n
              if (jpvt(j) /= 0) then
                 if (j /= nfxd) then
                    call la_zswap(m,a(1,j),1,a(1,nfxd),1)
                    jpvt(j) = jpvt(nfxd)
                    jpvt(nfxd) = j
                 else
                    jpvt(j) = j
                 end if
                 nfxd = nfxd + 1
              else
                 jpvt(j) = j
              end if
           end do
           nfxd = nfxd - 1
           ! factorize fixed columns
        ! =======================
           ! compute the qr factorization of fixed columns and update
           ! remaining columns.
           if (nfxd > 0) then
              na = min(m,nfxd)
