           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldt,m,n,nb
           ! Array Arguments
           complex(xdp),intent(inout) :: a(lda,*)
           complex(xdp),intent(out) :: t(ldt,*),work(*)
       ! =====================================================================
           ! Local Scalars
           logical(lk),parameter :: use_recursive_qr = .true.
           integer(ilp) :: i,ib,iinfo,k

           ! Executable Statements
           ! test the input arguments
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nb < 1 .or. (nb > min(m,n) .and. min(m,n) > 0)) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           else if (ldt < nb) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('YGEQRT',-info)
              return
           end if
           ! quick return if possible
           k = min(m,n)
           if (k == 0) return
           ! blocked loop of length k
           do i = 1,k,nb
              ib = min(k - i + 1,nb)
           ! compute the qr factorization of the current block a(i:m,i:i+ib-1)
              if (use_recursive_qr) then
                 call la_ygeqrt3(m - i + 1,ib,a(i,i),lda,t(1,i),ldt,iinfo)
              else
                 call la_ygeqrt2(m - i + 1,ib,a(i,i),lda,t(1,i),ldt,iinfo)
              end if
