                 call la_ylarfb('L','C','F','C',m - i + 1,n - i - ib + 1,ib,a(i,i),lda,t(1, &
                            i),ldt,a(i,i + ib),lda,work,n - i - ib + 1)
              end if
           end do
           return
     end subroutine la_ygeqrt
