              end do
              if (ii <= m) then
               ! multiply q to the last block of c
               call la_ytpmqrt('L','C',kk,n,k,0,nb,a(ii,1),lda,t(1,ctr*k + 1),ldt, &
                         c(1,1),ldc,c(ii,1),ldc,work,info)
              end if
           else if (right .and. tran) then
               ! multiply q to the last block of c
               kk = mod((n - k), (mb - k))
               ctr = (n - k)/(mb - k)
               if (kk > 0) then
                 ii = n - kk + 1
                 call la_ytpmqrt('R','C',m,kk,k,0,nb,a(ii,1),lda,t(1,ctr*k + 1),ldt, &
                            c(1,1),ldc,c(1,ii),ldc,work,info)
               else
                 ii = n + 1
               end if
               do i = ii - (mb - k),mb + 1,-(mb - k)
               ! multiply q to the current block of c (1:m,i:i+mb)
                 ctr = ctr - 1
                 call la_ytpmqrt('R','C',m,mb - k,k,0,nb,a(i,1),lda,t(1,ctr*k + 1), &
                           ldt,c(1,1),ldc,c(1,i),ldc,work,info)
               end do
               ! multiply q to the first block of c (1:m,1:mb)
               call la_ygemqrt('R','C',m,mb,k,nb,a(1,1),lda,t,ldt,c(1,1),ldc,work, &
                         info)
