#ifdef LA_WITH_QP
     !> WLAMTSQR: overwrites the general complex M-by-N matrix C with
     !> SIDE = 'L'     SIDE = 'R'
     !> TRANS = 'N':      Q * C          C * Q
     !> TRANS = 'C':      Q**H * C       C * Q**H
     !> where Q is a complex unitary matrix defined as the product
     !> of blocked elementary reflectors computed by tall skinny
     !> QR factorization (WLATSQR)

     pure subroutine la_wlamtsqr(side,trans,m,n,k,mb,nb,a,lda,t,ldt,c,ldc,work, &
               lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: side,trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n,k,mb,nb,ldt,lwork,ldc
           ! Array Arguments
           complex(qp),intent(in) :: a(lda,*),t(ldt,*)
           complex(qp),intent(out) :: work(*)
           complex(qp),intent(inout) :: c(ldc,*)
       ! =====================================================================
           ! Local Scalars
           logical(lk) :: left,right,tran,notran,lquery
           integer(ilp) :: i,ii,kk,lw,ctr,q
           ! External Subroutines
           ! Executable Statements
           ! test the input arguments
           lquery = lwork < 0
           notran = la_lsame(trans,'N')
           tran = la_lsame(trans,'C')
           left = la_lsame(side,'L')
           right = la_lsame(side,'R')
           if (left) then
             lw = n*nb
             q = m
           else
             lw = m*nb
             q = n
           end if
           info = 0
           if (.not. left .and. .not. right) then
              info = -1
           else if (.not. tran .and. .not. notran) then
              info = -2
           else if (m < k) then
             info = -3
           else if (n < 0) then
             info = -4
           else if (k < 0) then
             info = -5
           else if (k < nb .or. nb < 1) then
             info = -7
           else if (lda < max(1,q)) then
             info = -9
           else if (ldt < max(1,nb)) then
             info = -11
           else if (ldc < max(1,m)) then
              info = -13
           else if ((lwork < max(1,lw)) .and. (.not. lquery)) then
             info = -15
           end if
           ! determine the block size if it is tall skinny or short and wide
           if (info == 0) then
               work(1) = lw
           end if
           if (info /= 0) then
             call la_xerbla('WLAMTSQR',-info)
             return
           else if (lquery) then
            return
           end if
           ! quick return if possible
           if (min(m,n,k) == 0) then
             return
           end if
           if ((mb <= k) .or. (mb >= max(m,n,k))) then
             call la_wgemqrt(side,trans,m,n,k,nb,a,lda,t,ldt,c,ldc,work,info)

             return
            end if
           if (left .and. notran) then
               ! multiply q to the last block of c
              kk = mod((m - k), (mb - k))
              ctr = (m - k)/(mb - k)
              if (kk > 0) then
                ii = m - kk + 1
                call la_wtpmqrt('L','N',kk,n,k,0,nb,a(ii,1),lda,t(1,ctr*k + 1),ldt, &
                           c(1,1),ldc,c(ii,1),ldc,work,info)
              else
                ii = m + 1
              end if
              do i = ii - (mb - k),mb + 1,-(mb - k)
               ! multiply q to the current block of c (i:i+mb,1:n)
                ctr = ctr - 1
                call la_wtpmqrt('L','N',mb - k,n,k,0,nb,a(i,1),lda,t(1,ctr*k + 1),ldt, &
                          c(1,1),ldc,c(i,1),ldc,work,info)
              end do
               ! multiply q to the first block of c (1:mb,1:n)
              call la_wgemqrt('L','N',mb,n,k,nb,a(1,1),lda,t,ldt,c(1,1),ldc,work, &
                        info)
           else if (left .and. tran) then
               ! multiply q to the first block of c
              kk = mod((m - k), (mb - k))
              ii = m - kk + 1
              ctr = 1
              call la_wgemqrt('L','C',mb,n,k,nb,a(1,1),lda,t,ldt,c(1,1),ldc,work, &
                        info)
              do i = mb + 1,ii - mb + k, (mb - k)
               ! multiply q to the current block of c (i:i+mb,1:n)
               call la_wtpmqrt('L','C',mb - k,n,k,0,nb,a(i,1),lda,t(1,ctr*k + 1),ldt,c( &
                         1,1),ldc,c(i,1),ldc,work,info)
               ctr = ctr + 1
              end do
              if (ii <= m) then
               ! multiply q to the last block of c
               call la_wtpmqrt('L','C',kk,n,k,0,nb,a(ii,1),lda,t(1,ctr*k + 1),ldt, &
                         c(1,1),ldc,c(ii,1),ldc,work,info)
              end if
           else if (right .and. tran) then
               ! multiply q to the last block of c
               kk = mod((n - k), (mb - k))
               ctr = (n - k)/(mb - k)
               if (kk > 0) then
                 ii = n - kk + 1
                 call la_wtpmqrt('R','C',m,kk,k,0,nb,a(ii,1),lda,t(1,ctr*k + 1),ldt, &
                            c(1,1),ldc,c(1,ii),ldc,work,info)
               else
                 ii = n + 1
               end if
               do i = ii - (mb - k),mb + 1,-(mb - k)
               ! multiply q to the current block of c (1:m,i:i+mb)
                 ctr = ctr - 1
                 call la_wtpmqrt('R','C',m,mb - k,k,0,nb,a(i,1),lda,t(1,ctr*k + 1), &
                           ldt,c(1,1),ldc,c(1,i),ldc,work,info)
               end do
               ! multiply q to the first block of c (1:m,1:mb)
               call la_wgemqrt('R','C',m,mb,k,nb,a(1,1),lda,t,ldt,c(1,1),ldc,work, &
                         info)
           else if (right .and. notran) then
               ! multiply q to the first block of c
              kk = mod((n - k), (mb - k))
              ii = n - kk + 1
              ctr = 1
              call la_wgemqrt('R','N',m,mb,k,nb,a(1,1),lda,t,ldt,c(1,1),ldc,work, &
                        info)
              do i = mb + 1,ii - mb + k, (mb - k)
               ! multiply q to the current block of c (1:m,i:i+mb)
               call la_wtpmqrt('R','N',m,mb - k,k,0,nb,a(i,1),lda,t(1,ctr*k + 1),ldt, &
