     !> CGEMQR: overwrites the general real M-by-N matrix C with
     !> SIDE = 'L'     SIDE = 'R'
     !> TRANS = 'N':      Q * C          C * Q
     !> TRANS = 'T':      Q**H * C       C * Q**H
     !> where Q is a complex unitary matrix defined as the product
     !> of blocked elementary reflectors computed by tall skinny
     !> QR factorization (CGEQR)

     pure subroutine la_cgemqr(side,trans,m,n,k,a,lda,t,tsize,c,ldc,work,lwork, &
               info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: side,trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n,k,tsize,lwork,ldc
           ! Array Arguments
           complex(sp),intent(in) :: a(lda,*),t(*)
           complex(sp),intent(inout) :: c(ldc,*)
           complex(sp),intent(out) :: work(*)
       ! =====================================================================
           ! Local Scalars
           logical(lk) :: left,right,tran,notran,lquery
           integer(ilp) :: mb,nb,lw,nblcks,mn
           ! Intrinsic Functions
           intrinsic :: int,max,min,mod
           ! Executable Statements
           ! test the input arguments
           lquery = lwork == -1
           notran = la_lsame(trans,'N')
           tran = la_lsame(trans,'C')
           left = la_lsame(side,'L')
           right = la_lsame(side,'R')
           mb = int(t(2),KIND=ilp)
           nb = int(t(3),KIND=ilp)
           if (left) then
             lw = n*nb
             mn = m
           else
             lw = mb*nb
             mn = n
           end if
           if ((mb > k) .and. (mn > k)) then
             if (mod(mn - k,mb - k) == 0) then
               nblcks = (mn - k)/(mb - k)
             else
               nblcks = (mn - k)/(mb - k) + 1
             end if
           else
             nblcks = 1
           end if
           info = 0
           if (.not. left .and. .not. right) then
             info = -1
           else if (.not. tran .and. .not. notran) then
             info = -2
           else if (m < 0) then
             info = -3
           else if (n < 0) then
             info = -4
           else if (k < 0 .or. k > mn) then
             info = -5
           else if (lda < max(1,mn)) then
             info = -7
           else if (tsize < 5) then
             info = -9
           else if (ldc < max(1,m)) then
             info = -11
           else if ((lwork < max(1,lw)) .and. (.not. lquery)) then
             info = -13
           end if
           if (info == 0) then
             work(1) = lw
           end if
           if (info /= 0) then
             call la_xerbla('CGEMQR',-info)
             return
           else if (lquery) then
             return
           end if
           ! quick return if possible
           if (min(m,n,k) == 0) then
             return
           end if
           if ((left .and. m <= k) .or. (right .and. n <= k) .or. (mb <= k) .or. (mb >= max(m,n, &
                     k))) then
             call la_cgemqrt(side,trans,m,n,k,nb,a,lda,t(6),nb,c,ldc,work,info &
                       )
           else
             call la_clamtsqr(side,trans,m,n,k,mb,nb,a,lda,t(6),nb,c,ldc,work, &
                       lwork,info)
           end if
           work(1) = lw
           return
     end subroutine la_cgemqr
