           else if (n < 0) then
             info = -2
           else if (lda < max(1,m)) then
             info = -4
           else if (tsize < max(1,nb*n*nblcks + 5) .and. (.not. lquery) .and. (.not. lminws)) &
                     then
             info = -6
           else if ((lwork < max(1,n*nb)) .and. (.not. lquery) .and. (.not. lminws)) &
                     then
             info = -8
           end if
           if (info == 0) then
             if (mint) then
               t(1) = mintsz
             else
               t(1) = nb*n*nblcks + 5
             end if
             t(2) = mb
             t(3) = nb
             if (minw) then
               work(1) = max(1,n)
             else
               work(1) = max(1,nb*n)
             end if
           end if
           if (info /= 0) then
